package com.example;

import com.example.history.LearnedHistoryStore;
import com.example.search.SearchService;
import net.runelite.api.coords.WorldPoint;

import javax.swing.SwingUtilities;
import java.util.Objects;
import java.util.function.Consumer;

/** Shared destination selection for sidebar and future palette. */
public final class DestinationSelectionService
{
	private final DestinationService destinationService;
	private final LearnedHistoryStore historyStore;
	private final Consumer<Runnable> historyExecutor;

	public DestinationSelectionService(DestinationService destinationService, LearnedHistoryStore historyStore)
	{
		this(destinationService, historyStore, SwingUtilities::invokeLater);
	}

	public DestinationSelectionService(DestinationService destinationService, LearnedHistoryStore historyStore,
		Consumer<Runnable> historyExecutor)
	{
		this.destinationService = Objects.requireNonNull(destinationService, "destinationService");
		this.historyStore = historyStore;
		this.historyExecutor = Objects.requireNonNull(historyExecutor, "historyExecutor");
	}

	public void select(String destinationId, WorldPoint target, String query)
	{
		select(destinationId, target, query, posted -> {});
	}

	/** Reports whether a Shortest Path path request was posted; completion runs on the EDT. */
	public void select(String destinationId, WorldPoint target, String query, Consumer<Boolean> onComplete)
	{
		Objects.requireNonNull(onComplete, "onComplete");
		if (destinationId == null || destinationId.isBlank() || target == null)
		{
			historyExecutor.accept(() -> onComplete.accept(false));
			return;
		}
		String normalizedQuery = SearchService.normalize(query);
		destinationService.setDestination(target, posted -> historyExecutor.accept(() ->
		{
			try
			{
				if (posted && historyStore != null)
				{
					historyStore.recordSelection(destinationId, normalizedQuery);
				}
			}
			finally
			{
				onComplete.accept(posted);
			}
		}));
	}
}

package com.example;

import com.google.inject.Inject;
import net.runelite.api.Client;
import net.runelite.api.Player;
import net.runelite.api.coords.WorldPoint;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.eventbus.EventBus;
import net.runelite.client.events.PluginMessage;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;

import java.util.HashMap;
import java.util.Map;
import java.util.Objects;
import java.util.function.Consumer;

public final class DestinationService
{
	private static final Logger log = LoggerFactory.getLogger(DestinationService.class);

	private final Client client;
	private final ClientThread clientThread;
	private final EventBus eventBus;

	@Inject
	public DestinationService(Client client, ClientThread clientThread, EventBus eventBus)
	{
		this.client = client;
		this.clientThread = clientThread;
		this.eventBus = eventBus;
	}

	public void setDestination(WorldPoint target)
	{
		setDestination(target, () -> {});
	}

	/** Calls onDispatched only after the Shortest Path path message was posted. */
	public void setDestination(WorldPoint target, Runnable onDispatched)
	{
		Objects.requireNonNull(onDispatched, "onDispatched");
		setDestination(target, posted ->
		{
			if (posted)
			{
				onDispatched.run();
			}
		});
	}

	/** Completes after the Shortest Path path message is posted, or when dispatch is rejected. */
	public void setDestination(WorldPoint target, Consumer<Boolean> onComplete)
	{
		Objects.requireNonNull(onComplete, "onComplete");
		if (target == null)
		{
			onComplete.accept(false);
			return;
		}

		clientThread.invokeLater(() ->
		{
			Player localPlayer = client.getLocalPlayer();
			if (localPlayer == null)
			{
				log.debug("Ignoring destination set because local player is null. target={}", target);
				onComplete.accept(false);
				return;
			}

			Map<String, Object> data = new HashMap<>();
			data.put("start", localPlayer.getWorldLocation());
			data.put("target", target);

			log.debug("Posting Shortest Path destination. start={} target={}", localPlayer.getWorldLocation(), target);
			try
			{
				eventBus.post(new PluginMessage("shortestpath", "path", data));
			}
			catch (RuntimeException e)
			{
				onComplete.accept(false);
				throw e;
			}
			onComplete.accept(true);
		});
	}

	public void clear()
	{
		eventBus.post(new PluginMessage("shortestpath", "clear"));
	}
}

package com.example;

import java.awt.event.InputEvent;
import java.awt.event.KeyEvent;
import net.runelite.client.config.Config;
import net.runelite.client.config.ConfigGroup;
import net.runelite.client.config.ConfigItem;
import net.runelite.client.config.Keybind;

@ConfigGroup("takemethere")
public interface TakeMeThereConfig extends Config
{
	Keybind DEFAULT_PALETTE_HOTKEY = new Keybind(KeyEvent.VK_T, InputEvent.CTRL_DOWN_MASK);

	@ConfigItem(
		keyName = "paletteHotkey",
		name = "Quick search hotkey",
		description = "Open or close quick destination search.",
		position = 0
	)
	default Keybind paletteHotkey()
	{
		return DEFAULT_PALETTE_HOTKEY;
	}
}

package com.example;

import com.example.data.LocationCatalogLoader;
import com.example.custom.CustomLocationsStore;
import com.example.favourites.FavouritesStore;
import com.example.history.LearnedHistoryStore;
import com.example.model.LocationCatalog;
import com.example.onboarding.PaletteTipState;
import com.example.palette.DestinationPaletteDialog;
import com.example.palette.PaletteHotkeyController;
import com.example.search.SearchMetadata;
import com.example.search.SearchService;
import com.example.ui.TakeMeTherePanel;
import com.google.gson.Gson;
import com.google.inject.Provides;
import net.runelite.api.Client;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.events.ConfigChanged;
import net.runelite.client.input.KeyManager;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;
import net.runelite.client.ui.ClientToolbar;
import net.runelite.client.ui.NavigationButton;
import net.runelite.client.util.ImageUtil;

import javax.inject.Inject;
import javax.swing.SwingUtilities;
import java.awt.Component;
import java.awt.Window;
import java.awt.image.BufferedImage;
import java.util.concurrent.atomic.AtomicInteger;

@PluginDescriptor(
	name = "Take Me There"
)
public class TakeMeTherePlugin extends Plugin
{
	@Inject
	private ClientToolbar clientToolbar;

	@Inject
	private ConfigManager configManager;

	@Inject
	private DestinationService destinationService;

	@Inject
	private Gson gson;

	@Inject
	private Client client;

	@Inject
	private KeyManager keyManager;

	@Inject
	private TakeMeThereConfig config;

	private NavigationButton navigationButton;
	private DestinationPaletteDialog palette;
	private PaletteHotkeyController paletteHotkeys;
	private volatile PaletteTipState paletteTipState;
	private TakeMeTherePanel panel;
	private final AtomicInteger lifecycleGeneration = new AtomicInteger();

	@Provides
	TakeMeThereConfig provideConfig(ConfigManager manager)
	{
		return manager.getConfig(TakeMeThereConfig.class);
	}

	@Override
	protected void startUp()
	{
		int generation = lifecycleGeneration.incrementAndGet();
		SwingUtilities.invokeLater(() ->
		{
			if (generation != lifecycleGeneration.get())
			{
				return;
			}
			disposeUi();
			FavouritesStore favouritesStore = new FavouritesStore(configManager, gson);
			CustomLocationsStore customLocationsStore = new CustomLocationsStore(configManager, gson);

			LocationCatalog catalog = new LocationCatalogLoader(gson).load();
			LearnedHistoryStore historyStore = new LearnedHistoryStore(configManager, gson);
			SearchService searchService = new SearchService(SearchMetadata.load(gson, catalog), historyStore);
			DestinationSelectionService selectionService = new DestinationSelectionService(destinationService, historyStore);
			PaletteTipState tipState = new PaletteTipState(configManager);
			TakeMeTherePanel newPanel = new TakeMeTherePanel(
				catalog,
				favouritesStore,
				customLocationsStore,
				searchService,
				selectionService
			);
			newPanel.setPaletteTipVisible(tipState.reconcile(config.paletteHotkey()));
			paletteTipState = tipState;
			panel = newPanel;
			Window owner = SwingUtilities.getWindowAncestor((Component) client);
			if (owner == null)
			{
				throw new IllegalStateException("RuneLite client window is unavailable");
			}
			palette = new DestinationPaletteDialog(owner, client::getCanvas, catalog, customLocationsStore,
				searchService, historyStore, selectionService);
			paletteHotkeys = new PaletteHotkeyController(config::paletteHotkey, palette,
				usedHotkey ->
				{
					tipState.openedWith(usedHotkey);
					newPanel.setPaletteTipVisible(tipState.shouldShow(config.paletteHotkey()));
				},
				keyManager::registerKeyListener, keyManager::unregisterKeyListener);

			BufferedImage icon = ImageUtil.loadImageResource(TakeMeTherePlugin.class, "/panel_icon.png");

			navigationButton = NavigationButton.builder()
				.tooltip("Take Me There")
				.icon(icon)
				.panel(newPanel)
				.build();

			clientToolbar.addNavigation(navigationButton);
			paletteHotkeys.start();
		});
	}

	@Override
	protected void shutDown()
	{
		lifecycleGeneration.incrementAndGet();
		SwingUtilities.invokeLater(this::disposeUi);
	}

	@Subscribe
	public void onConfigChanged(ConfigChanged event)
	{
		if ("takemethere".equals(event.getGroup()) && "paletteHotkey".equals(event.getKey()))
		{
			PaletteTipState tipState = paletteTipState;
			if (tipState != null)
			{
				// ConfigManager posts this event after updating the config proxy.
				tipState.reconcile(config.paletteHotkey());
			}
			SwingUtilities.invokeLater(() ->
			{
				if (paletteHotkeys != null)
				{
					paletteHotkeys.configurationChanged();
				}
				if (tipState != null && tipState == paletteTipState && panel != null)
				{
					panel.setPaletteTipVisible(tipState.shouldShow(config.paletteHotkey()));
				}
			});
		}
	}

	private void disposeUi()
	{
		if (paletteHotkeys != null)
		{
			paletteHotkeys.stop();
			paletteHotkeys = null;
			palette = null;
		}
		else if (palette != null)
		{
			palette.disposePalette();
			palette = null;
		}
		if (navigationButton != null)
		{
			clientToolbar.removeNavigation(navigationButton);
			navigationButton = null;
		}
		panel = null;
		paletteTipState = null;
	}
}

package com.example.custom;

import java.util.Objects;

public final class CustomLocation
{
	private final String id;
	private final String name;
	private final String categoryId;
	private final int x;
	private final int y;
	private final int plane;

	public CustomLocation(String id, String name, String categoryId, int x, int y, int plane)
	{
		this.id = Objects.requireNonNull(id, "id");
		this.name = Objects.requireNonNull(name, "name");
		this.categoryId = Objects.requireNonNull(categoryId, "categoryId");
		this.x = x;
		this.y = y;
		this.plane = plane;
	}

	public String getId()
	{
		return id;
	}

	public String getName()
	{
		return name;
	}

	public String getCategoryId()
	{
		return categoryId;
	}

	public int getX()
	{
		return x;
	}

	public int getY()
	{
		return y;
	}

	public int getPlane()
	{
		return plane;
	}

	@Override
	public boolean equals(Object o)
	{
		if (this == o) return true;
		if (!(o instanceof CustomLocation)) return false;
		CustomLocation that = (CustomLocation) o;
		return id.equals(that.id);
	}

	@Override
	public int hashCode()
	{
		return id.hashCode();
	}
}

package com.example.custom;

import com.google.gson.Gson;
import com.google.gson.reflect.TypeToken;
import net.runelite.client.config.ConfigManager;

import java.lang.reflect.Type;
import java.util.ArrayList;
import java.util.List;
import java.util.Objects;

public final class CustomLocationsStore
{
	private static final String CONFIG_GROUP = "takemethere";
	private static final String KEY_CUSTOM_LOCATIONS = "customLocations";

	private static final Type LIST_TYPE = new TypeToken<ArrayList<CustomLocation>>() {}.getType();

	private final ConfigManager configManager;
	private final Gson gson;

	public CustomLocationsStore(ConfigManager configManager, Gson gson)
	{
		this.configManager = Objects.requireNonNull(configManager, "configManager");
		this.gson = Objects.requireNonNull(gson, "gson");
	}

	public List<CustomLocation> load()
	{
		String raw = configManager.getConfiguration(CONFIG_GROUP, KEY_CUSTOM_LOCATIONS);
		if (raw == null || raw.isBlank())
		{
			return new ArrayList<>();
		}

		try
		{
			List<CustomLocation> parsed = gson.fromJson(raw, LIST_TYPE);
			return parsed == null ? new ArrayList<>() : new ArrayList<>(parsed);
		}
		catch (Exception e)
		{
			return new ArrayList<>();
		}
	}

	public void save(List<CustomLocation> locations)
	{
		String raw = gson.toJson(Objects.requireNonNull(locations, "locations"), LIST_TYPE);
		configManager.setConfiguration(CONFIG_GROUP, KEY_CUSTOM_LOCATIONS, raw);
	}
}

package com.example.custom.ui;

import com.example.custom.CustomLocation;
import com.example.custom.CustomLocationsStore;

import javax.swing.*;
import javax.swing.table.AbstractTableModel;
import java.awt.*;
import java.util.ArrayList;
import java.util.List;
import java.util.Objects;
import java.util.UUID;

public final class CustomLocationsManagerDialog extends JDialog
{
	private static final String CUSTOM_CATEGORY_ID = "custom";
	private static final String CUSTOM_CATEGORY_NAME = "Custom Locations";

	private final CustomLocationsStore store;

	private final CustomLocationsTableModel tableModel = new CustomLocationsTableModel();
	private final JTable table = new JTable(tableModel);

	private final JButton addButton = new JButton("Add");
	private final JButton editButton = new JButton("Edit");
	private final JButton deleteButton = new JButton("Delete");
	private final JButton closeButton = new JButton("Close");

	public CustomLocationsManagerDialog(Window owner, CustomLocationsStore store)
	{
		super(owner, "Take Me There - Custom Locations");
		this.store = Objects.requireNonNull(store, "store");

		setDefaultCloseOperation(WindowConstants.HIDE_ON_CLOSE);
		setMinimumSize(new Dimension(700, 420));
		setSize(700, 420);
		setLocationRelativeTo(owner);

		initUi();
		loadFromStore();
	}

	private void initUi()
	{
		setLayout(new BorderLayout(8, 8));

		table.setSelectionMode(ListSelectionModel.SINGLE_SELECTION);
		table.setFillsViewportHeight(true);
		table.getSelectionModel().addListSelectionListener(e -> updateButtons());

		add(new JScrollPane(table), BorderLayout.CENTER);

		JPanel actions = new JPanel(new FlowLayout(FlowLayout.LEFT, 8, 8));
		actions.add(addButton);
		actions.add(editButton);
		actions.add(deleteButton);

		JPanel bottom = new JPanel(new BorderLayout());
		bottom.add(actions, BorderLayout.WEST);

		JPanel right = new JPanel(new FlowLayout(FlowLayout.RIGHT, 8, 8));
		right.add(closeButton);
		bottom.add(right, BorderLayout.EAST);

		add(bottom, BorderLayout.SOUTH);

		addButton.addActionListener(e -> onAdd());
		editButton.addActionListener(e -> onEdit());
		deleteButton.addActionListener(e -> onDelete());
		closeButton.addActionListener(e -> setVisible(false));

		updateButtons();
	}

	private void loadFromStore()
	{
		tableModel.setRows(store.load());
		updateButtons();
	}

	private void persist()
	{
		store.save(tableModel.getRows());
	}

	private void updateButtons()
	{
		boolean hasSelection = table.getSelectedRow() >= 0;
		editButton.setEnabled(hasSelection);
		deleteButton.setEnabled(hasSelection);
	}

	private void onAdd()
	{
		CustomLocationEditor editor = new CustomLocationEditor(this, null);
		editor.setVisible(true);

		CustomLocation created = editor.getResult();
		if (created == null)
		{
			return;
		}

		tableModel.add(created);
		persist();
	}

	private void onEdit()
	{
		int row = table.getSelectedRow();
		if (row < 0)
		{
			return;
		}

		CustomLocation existing = tableModel.getAt(row);
		CustomLocationEditor editor = new CustomLocationEditor(this, existing);
		editor.setVisible(true);

		CustomLocation updated = editor.getResult();
		if (updated == null)
		{
			return;
		}

		tableModel.update(row, updated);
		persist();
	}

	private void onDelete()
	{
		int row = table.getSelectedRow();
		if (row < 0)
		{
			return;
		}

		CustomLocation existing = tableModel.getAt(row);

		int confirm = JOptionPane.showConfirmDialog(
			this,
			"Delete \"" + existing.getName() + "\"?",
			"Delete Custom Location",
			JOptionPane.OK_CANCEL_OPTION,
			JOptionPane.WARNING_MESSAGE
		);

		if (confirm != JOptionPane.OK_OPTION)
		{
			return;
		}

		tableModel.remove(row);
		persist();
	}

	private static final class CustomLocationsTableModel extends AbstractTableModel
	{
		private static final String[] COLS = {"Name", "Category", "X", "Y", "Plane"};
		private final List<CustomLocation> rows = new ArrayList<>();

		void setRows(List<CustomLocation> newRows)
		{
			rows.clear();
			if (newRows != null)
			{
				rows.addAll(newRows);
			}
			fireTableDataChanged();
		}

		List<CustomLocation> getRows()
		{
			return new ArrayList<>(rows);
		}

		CustomLocation getAt(int row)
		{
			return rows.get(row);
		}

		void add(CustomLocation location)
		{
			rows.add(location);
			int idx = rows.size() - 1;
			fireTableRowsInserted(idx, idx);
		}

		void update(int row, CustomLocation location)
		{
			rows.set(row, location);
			fireTableRowsUpdated(row, row);
		}

		void remove(int row)
		{
			rows.remove(row);
			fireTableRowsDeleted(row, row);
		}

		@Override
		public int getRowCount()
		{
			return rows.size();
		}

		@Override
		public int getColumnCount()
		{
			return COLS.length;
		}

		@Override
		public String getColumnName(int column)
		{
			return COLS[column];
		}

		@Override
		public Object getValueAt(int rowIndex, int columnIndex)
		{
			CustomLocation l = rows.get(rowIndex);
			switch (columnIndex)
			{
				case 0:
					return l.getName();
				case 1:
					return CUSTOM_CATEGORY_NAME;
				case 2:
					return l.getX();
				case 3:
					return l.getY();
				case 4:
					return l.getPlane();
				default:
					return "";
			}
		}

		@Override
		public Class<?> getColumnClass(int columnIndex)
		{
			if (columnIndex >= 2)
			{
				return Integer.class;
			}
			return String.class;
		}

		@Override
		public boolean isCellEditable(int rowIndex, int columnIndex)
		{
			return false;
		}
	}

	private static final class CustomLocationEditor extends JDialog
	{
		private final JTextField nameField = new JTextField();
		private final JTextField categoryField = new JTextField(CUSTOM_CATEGORY_NAME);
		private final JSpinner xSpinner = new JSpinner(new SpinnerNumberModel(0, 0, 10000, 1));
		private final JSpinner ySpinner = new JSpinner(new SpinnerNumberModel(0, 0, 10000, 1));
		private final JSpinner planeSpinner = new JSpinner(new SpinnerNumberModel(0, 0, 3, 1));

		private CustomLocation result;

		private final String existingId;

		CustomLocationEditor(Window owner, CustomLocation existing)
		{
			super(owner, existing == null ? "Add Custom Location" : "Edit Custom Location", ModalityType.APPLICATION_MODAL);

			this.existingId = existing == null ? null : existing.getId();

			setDefaultCloseOperation(WindowConstants.DISPOSE_ON_CLOSE);
			setSize(420, 260);
			setLocationRelativeTo(owner);

			categoryField.setEditable(false);

			initUi();

			if (existing != null)
			{
				nameField.setText(existing.getName());
				xSpinner.setValue(existing.getX());
				ySpinner.setValue(existing.getY());
				planeSpinner.setValue(existing.getPlane());
			}
		}

		CustomLocation getResult()
		{
			return result;
		}

		private void initUi()
		{
			JPanel form = new JPanel(new GridBagLayout());
			GridBagConstraints c = new GridBagConstraints();
			c.insets = new Insets(6, 6, 6, 6);
			c.fill = GridBagConstraints.HORIZONTAL;
			c.weightx = 1;

			int row = 0;

			addRow(form, c, row++, "Name", nameField);
			addRow(form, c, row++, "Category", categoryField);
			addRow(form, c, row++, "X", xSpinner);
			addRow(form, c, row++, "Y", ySpinner);
			addRow(form, c, row++, "Plane", planeSpinner);

			JButton ok = new JButton("Save");
			JButton cancel = new JButton("Cancel");

			ok.addActionListener(e -> onSave());
			cancel.addActionListener(e -> dispose());

			JPanel buttons = new JPanel(new FlowLayout(FlowLayout.RIGHT, 8, 8));
			buttons.add(cancel);
			buttons.add(ok);

			setLayout(new BorderLayout());
			add(form, BorderLayout.CENTER);
			add(buttons, BorderLayout.SOUTH);
		}

		private void addRow(JPanel panel, GridBagConstraints c, int row, String label, JComponent field)
		{
			c.gridx = 0;
			c.gridy = row;
			c.weightx = 0;
			panel.add(new JLabel(label), c);

			c.gridx = 1;
			c.gridy = row;
			c.weightx = 1;
			panel.add(field, c);
		}

		private void onSave()
		{
			String name = nameField.getText() == null ? "" : nameField.getText().trim();
			if (name.isEmpty())
			{
				JOptionPane.showMessageDialog(this, "Name is required.", "Validation", JOptionPane.WARNING_MESSAGE);
				return;
			}

			int x = (Integer) xSpinner.getValue();
			int y = (Integer) ySpinner.getValue();
			int plane = (Integer) planeSpinner.getValue();

			String id = existingId != null ? existingId : "custom:" + UUID.randomUUID();

			result = new CustomLocation(id, name, CUSTOM_CATEGORY_ID, x, y, plane);
			dispose();
		}
	}
}

package com.example.data;

import com.example.model.CategoryDefinition;
import com.example.model.LocationCatalog;
import com.example.model.LocationDefinition;
import com.google.gson.Gson;
import com.google.gson.reflect.TypeToken;

import java.io.InputStream;
import java.io.InputStreamReader;
import java.io.Reader;
import java.lang.reflect.Type;
import java.nio.charset.StandardCharsets;
import java.util.*;

public final class LocationCatalogLoader
{
	private static final String BASE_PATH = "/takemethere/";
	private static final String CATEGORIES_FILE = "categories.json";

	private final Gson gson;

	public LocationCatalogLoader(Gson gson)
	{
		this.gson = Objects.requireNonNull(gson, "gson");
	}

	public LocationCatalog load()
	{
		List<CategoryDefinition> categories = loadCategories();

		Map<String, List<LocationDefinition>> byCategory = new LinkedHashMap<>();
		Map<String, LocationDefinition> byId = new LinkedHashMap<>();

		for (CategoryDefinition category : categories)
		{
			String categoryId = category.getId();
			String filename = categoryId + ".json";

			List<LocationDefinition> locations = loadLocationsFile(filename);

			for (LocationDefinition loc : locations)
			{
				if (byId.containsKey(loc.getId()))
				{
					throw new IllegalStateException("Duplicate location id: " + loc.getId());
				}
				byId.put(loc.getId(), loc);
			}

			byCategory.put(categoryId, List.copyOf(locations));
		}

		return new LocationCatalog(categories, byCategory, byId);
	}

	private List<CategoryDefinition> loadCategories()
	{
		Type type = new TypeToken<List<CategoryDefinition>>() {}.getType();
		List<CategoryDefinition> categories = readJson(CATEGORIES_FILE, type);

		if (categories.isEmpty())
		{
			throw new IllegalStateException("No categories found in " + CATEGORIES_FILE);
		}

		Set<String> seen = new HashSet<>();
		for (CategoryDefinition c : categories)
		{
			if (!seen.add(c.getId()))
			{
				throw new IllegalStateException("Duplicate category id: " + c.getId());
			}
		}

		return List.copyOf(categories);
	}

	private List<LocationDefinition> loadLocationsFile(String filename)
	{
		Type type = new TypeToken<List<LocationDefinition>>() {}.getType();
		return List.copyOf(readJson(filename, type));
	}

	private <T> T readJson(String filename, Type type)
	{
		String resourcePath = BASE_PATH + filename;

		InputStream in = LocationCatalogLoader.class.getResourceAsStream(resourcePath);
		if (in == null)
		{
			throw new IllegalStateException("Missing resource: " + resourcePath);
		}

		try (Reader reader = new InputStreamReader(in, StandardCharsets.UTF_8))
		{
			return gson.fromJson(reader, type);
		}
		catch (Exception e)
		{
			throw new IllegalStateException("Failed to read resource: " + resourcePath, e);
		}
	}
}

package com.example.favourites;

import com.google.gson.Gson;
import com.google.gson.reflect.TypeToken;
import net.runelite.client.config.ConfigManager;

import java.lang.reflect.Type;
import java.util.LinkedHashSet;
import java.util.Objects;
import java.util.Set;

public final class FavouritesStore
{
	private static final String CONFIG_GROUP = "takemethere";
	private static final String KEY_FAVOURITES = "favourites";

	private static final Type SET_TYPE = new TypeToken<LinkedHashSet<String>>() {}.getType();

	private final ConfigManager configManager;
	private final Gson gson;

	public FavouritesStore(ConfigManager configManager, Gson gson)
	{
		this.configManager = Objects.requireNonNull(configManager, "configManager");
		this.gson = Objects.requireNonNull(gson, "gson");
	}

	public LinkedHashSet<String> load()
	{
		String raw = configManager.getConfiguration(CONFIG_GROUP, KEY_FAVOURITES);
		if (raw == null || raw.isBlank())
		{
			return new LinkedHashSet<>();
		}

		try
		{
			LinkedHashSet<String> parsed = gson.fromJson(raw, SET_TYPE);
			return parsed == null ? new LinkedHashSet<>() : new LinkedHashSet<>(parsed);
		}
		catch (Exception e)
		{
			// If config is corrupted, don't crash the plugin; reset to empty.
			return new LinkedHashSet<>();
		}
	}

	public void save(Set<String> favouriteIds)
	{
		LinkedHashSet<String> stable = new LinkedHashSet<>(Objects.requireNonNull(favouriteIds, "favouriteIds"));
		String raw = gson.toJson(stable, SET_TYPE);
		configManager.setConfiguration(CONFIG_GROUP, KEY_FAVOURITES, raw);
	}

	public boolean isFavourite(String locationId)
	{
		return load().contains(Objects.requireNonNull(locationId, "locationId"));
	}

	public void add(String locationId)
	{
		Objects.requireNonNull(locationId, "locationId");
		LinkedHashSet<String> favourites = load();
		if (favourites.add(locationId))
		{
			save(favourites);
		}
	}

	public void remove(String locationId)
	{
		Objects.requireNonNull(locationId, "locationId");
		LinkedHashSet<String> favourites = load();
		if (favourites.remove(locationId))
		{
			save(favourites);
		}
	}
}

package com.example.history;

import com.example.search.SearchService;
import com.google.gson.Gson;
import com.google.gson.JsonObject;
import net.runelite.client.config.ConfigManager;

import java.util.ArrayList;
import java.util.HashMap;
import java.util.HashSet;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.Objects;
import java.util.Set;
import java.util.function.Consumer;
import java.util.function.Supplier;

/** Local selection requests sent to Shortest Path, not completed journeys. */
public final class LearnedHistoryStore
{
	public static final int MAX_QUERIES = 100;
	public static final int MAX_PER_QUERY = 5;
	public static final int MAX_GLOBAL = 200;
	public static final int MAX_RECENT = 20;
	public static final int MAX_COUNT = 1_000_000;
	private static final int MAX_ID_LENGTH = 160;
	private static final int MAX_QUERY_LENGTH = 120;
	private static final int VERSION = 1;
	private static final int MAX_JSON_LENGTH = 200_000;
	private static final String CONFIG_GROUP = "takemethere";
	private static final String CONFIG_KEY = "learnedSearchHistory";

	private final Supplier<String> read;
	private final Consumer<String> write;
	private final Runnable remove;
	private final Gson gson;
	private State state;

	public LearnedHistoryStore(ConfigManager configManager, Gson gson)
	{
		this(() -> configManager.getConfiguration(CONFIG_GROUP, CONFIG_KEY),
			value -> configManager.setConfiguration(CONFIG_GROUP, CONFIG_KEY, value),
			() -> configManager.unsetConfiguration(CONFIG_GROUP, CONFIG_KEY), gson);
	}

	LearnedHistoryStore(Supplier<String> read, Consumer<String> write, Runnable remove, Gson gson)
	{
		this.read = Objects.requireNonNull(read, "read");
		this.write = Objects.requireNonNull(write, "write");
		this.remove = Objects.requireNonNull(remove, "remove");
		this.gson = Objects.requireNonNull(gson, "gson");
		this.state = load();
	}

	public synchronized void recordSelection(String destinationId, String query)
	{
		if (!validId(destinationId))
		{
			return;
		}
		String normalizedQuery = SearchService.normalize(query);
		state.lastDestinationId = destinationId;
		increment(state.globalCounts, destinationId, MAX_GLOBAL, destinationId);
		state.recentIds.remove(destinationId);
		state.recentIds.add(0, destinationId);
		if (state.recentIds.size() > MAX_RECENT)
		{
			state.recentIds.remove(state.recentIds.size() - 1);
		}
		if (!normalizedQuery.isEmpty() && normalizedQuery.length() <= MAX_QUERY_LENGTH)
		{
			QueryRecord record = null;
			for (QueryRecord existing : state.queries)
			{
				if (existing.query.equals(normalizedQuery))
				{
					record = existing;
					break;
				}
			}
			if (record == null)
			{
				record = new QueryRecord(normalizedQuery);
			}
			else
			{
				state.queries.remove(record);
			}
			increment(record.counts, destinationId, MAX_PER_QUERY, destinationId);
			state.queries.add(record); // oldest query first; this is storage LRU only
			if (state.queries.size() > MAX_QUERIES)
			{
				state.queries.remove(0);
			}
		}
		write.accept(gson.toJson(state));
	}

	public synchronized RankingCounts countsFor(String query)
	{
		String normalizedQuery = SearchService.normalize(query);
		Map<String, Integer> queryCounts = Map.of();
		for (QueryRecord record : state.queries)
		{
			if (record.query.equals(normalizedQuery))
			{
				queryCounts = Map.copyOf(record.counts);
				break;
			}
		}
		return new RankingCounts(queryCounts, Map.copyOf(state.globalCounts));
	}

	public synchronized String lastDestinationId(Set<String> availableIds)
	{
		return state.lastDestinationId != null && availableIds.contains(state.lastDestinationId)
			? state.lastDestinationId : null;
	}

	public synchronized List<String> recentDestinationIds(Set<String> availableIds)
	{
		List<String> resolved = new ArrayList<>();
		for (String id : state.recentIds)
		{
			if (availableIds.contains(id))
			{
				resolved.add(id);
			}
		}
		return List.copyOf(resolved);
	}

	public synchronized Map<String, Integer> globalDestinationCounts()
	{
		return Map.copyOf(state.globalCounts);
	}

	public synchronized void clear()
	{
		remove.run();
		state = new State();
	}

	private State load()
	{
		try
		{
			String raw = read.get();
			if (raw == null || raw.isBlank() || raw.length() > MAX_JSON_LENGTH)
			{
				return new State();
			}
			JsonObject object = gson.fromJson(raw, JsonObject.class);
			if (object == null || !object.has("version") || !object.has("lastDestinationId")
				|| !object.has("globalCounts") || !object.has("queries") || !object.has("recentIds"))
			{
				return new State();
			}
			State parsed = gson.fromJson(object, State.class);
			return valid(parsed) ? parsed : new State();
		}
		catch (RuntimeException e)
		{
			return new State();
		}
	}

	private static boolean valid(State value)
	{
		if (value == null || value.version != VERSION || value.globalCounts == null
			|| value.queries == null || value.recentIds == null
			|| value.globalCounts.size() > MAX_GLOBAL || value.queries.size() > MAX_QUERIES
			|| value.recentIds.size() > MAX_RECENT || !validIdOrNull(value.lastDestinationId)
			|| !validCounts(value.globalCounts, MAX_GLOBAL))
		{
			return false;
		}
		Set<String> queries = new HashSet<>();
		for (QueryRecord record : value.queries)
		{
			if (record == null || record.query == null || record.query.isEmpty()
				|| record.query.length() > MAX_QUERY_LENGTH
				|| !record.query.equals(SearchService.normalize(record.query))
				|| !queries.add(record.query) || !validCounts(record.counts, MAX_PER_QUERY))
			{
				return false;
			}
		}
		Set<String> recent = new HashSet<>();
		for (String id : value.recentIds)
		{
			if (!validId(id) || !recent.add(id))
			{
				return false;
			}
		}
		return true;
	}

	private static boolean validCounts(Map<String, Integer> counts, int maximum)
	{
		if (counts == null || counts.size() > maximum)
		{
			return false;
		}
		for (Map.Entry<String, Integer> entry : counts.entrySet())
		{
			if (!validId(entry.getKey()) || entry.getValue() == null
				|| entry.getValue() < 1 || entry.getValue() > MAX_COUNT)
			{
				return false;
			}
		}
		return true;
	}

	private static boolean validId(String id)
	{
		return id != null && !id.isBlank() && id.length() <= MAX_ID_LENGTH;
	}

	private static boolean validIdOrNull(String id)
	{
		return id == null || validId(id);
	}

	private static void increment(Map<String, Integer> counts, String id, int maximum, String protectedId)
	{
		counts.put(id, Math.min(MAX_COUNT, counts.getOrDefault(id, 0) + 1));
		if (counts.size() > maximum)
		{
			String victim = counts.entrySet().stream()
				.filter(entry -> !entry.getKey().equals(protectedId))
				.min((left, right) ->
				{
					int byCount = Integer.compare(left.getValue(), right.getValue());
					return byCount != 0 ? byCount : right.getKey().compareTo(left.getKey());
				})
				.orElseThrow().getKey();
			counts.remove(victim);
		}
	}

	public static final class RankingCounts
	{
		private final Map<String, Integer> queryCounts;
		private final Map<String, Integer> globalCounts;

		private RankingCounts(Map<String, Integer> queryCounts, Map<String, Integer> globalCounts)
		{
			this.queryCounts = queryCounts;
			this.globalCounts = globalCounts;
		}

		public int queryCount(String id)
		{
			return queryCounts.getOrDefault(id, 0);
		}

		public int globalCount(String id)
		{
			return globalCounts.getOrDefault(id, 0);
		}
	}

	private static final class State
	{
		private int version = VERSION;
		private String lastDestinationId;
		private Map<String, Integer> globalCounts = new HashMap<>();
		private List<QueryRecord> queries = new ArrayList<>();
		private List<String> recentIds = new ArrayList<>();
	}

	private static final class QueryRecord
	{
		private String query;
		private Map<String, Integer> counts = new LinkedHashMap<>();

		private QueryRecord(String query)
		{
			this.query = query;
		}
	}
}

