package com.example.palette;

import com.example.custom.CustomLocation;
import com.example.custom.CustomLocationsStore;
import com.example.model.CategoryDefinition;
import com.example.model.LocationCatalog;
import com.example.model.LocationDefinition;
import net.runelite.api.coords.WorldPoint;

import java.util.ArrayList;
import java.util.List;

/** Resolves current built-in and custom destinations each time the palette opens. */
public final class PaletteDestinationSource
{
	private PaletteDestinationSource()
	{
	}

	public static List<PaletteDestination> load(LocationCatalog catalog, CustomLocationsStore customStore)
	{
		return from(catalog, customStore == null ? List.of() : customStore.load());
	}

	static List<PaletteDestination> from(LocationCatalog catalog, List<CustomLocation> customLocations)
	{
		List<PaletteDestination> destinations = new ArrayList<>();
		for (CategoryDefinition category : catalog.getCategories())
		{
			for (LocationDefinition location : catalog.getLocationsByCategoryId().getOrDefault(category.getId(), List.of()))
			{
				destinations.add(new PaletteDestination(location.getId(), location.getName(),
					category.getDisplayName(), new WorldPoint(location.getX(), location.getY(), location.getPlane())));
			}
		}
		for (CustomLocation location : customLocations)
		{
			if (location != null)
			{
				destinations.add(new PaletteDestination(location.getId(), location.getName(),
					"Custom Locations", new WorldPoint(location.getX(), location.getY(), location.getPlane())));
			}
		}
		return destinations;
	}
}

package com.example.palette;

import java.awt.event.KeyEvent;
import java.util.Objects;
import java.util.function.Consumer;
import java.util.function.Supplier;
import javax.swing.SwingUtilities;
import net.runelite.client.config.Keybind;
import net.runelite.client.input.KeyListener;
import net.runelite.client.util.HotkeyListener;

/** Opens the palette through RuneLite's keyboard listener. Dialog keys stay local to Swing. */
public final class PaletteHotkeyController
{
	public interface PaletteWindow
	{
		boolean isOpen();
		void open();
		void disposePalette();
		boolean ownsKeyEvent(KeyEvent event);
		void configureHotkey(Keybind keybind);
	}

	private final Supplier<Keybind> configuredKeybind;
	private final PaletteWindow palette;
	private final Consumer<Keybind> onOpened;
	private final Consumer<KeyListener> register;
	private final Consumer<KeyListener> unregister;
	private final HotkeyListener listener;
	private boolean started;

	public PaletteHotkeyController(Supplier<Keybind> configuredKeybind, PaletteWindow palette,
		Consumer<Keybind> onOpened, Consumer<KeyListener> register, Consumer<KeyListener> unregister)
	{
		this.configuredKeybind = Objects.requireNonNull(configuredKeybind, "configuredKeybind");
		this.palette = Objects.requireNonNull(palette, "palette");
		this.onOpened = Objects.requireNonNull(onOpened, "onOpened");
		this.register = Objects.requireNonNull(register, "register");
		this.unregister = Objects.requireNonNull(unregister, "unregister");
		this.listener = new HotkeyListener(this::keybind)
		{
			@Override
			public void keyPressed(KeyEvent event)
			{
				// Dialog-owned events must never reopen the palette after its local close action.
				if (palette.isOpen() || palette.ownsKeyEvent(event))
				{
					return;
				}
				super.keyPressed(event);
			}

			@Override
			public void hotkeyPressed()
			{
				if (started && !palette.isOpen())
				{
					Keybind usedHotkey = keybind();
					palette.open();
					if (palette.isOpen())
					{
						onOpened.accept(usedHotkey);
					}
					// The release can land in the newly focused dialog, away from KeyManager.
					SwingUtilities.invokeLater(() ->
					{
						if (started)
						{
							listener.focusLost();
						}
					});
				}
			}
		};
	}

	public void start()
	{
		if (started)
		{
			return;
		}
		started = true;
		palette.configureHotkey(keybind());
		register.accept(listener);
	}

	public void stop()
	{
		if (!started)
		{
			return;
		}
		started = false;
		unregister.accept(listener);
		listener.focusLost();
		palette.disposePalette();
	}

	public void configurationChanged()
	{
		listener.focusLost();
		palette.configureHotkey(keybind());
	}

	private Keybind keybind()
	{
		Keybind configured = configuredKeybind.get();
		return configured == null ? Keybind.NOT_SET : configured;
	}

}

package com.example.palette;

import java.awt.Component;
import java.awt.Container;
import java.awt.event.ActionEvent;
import java.awt.event.InputEvent;
import java.awt.event.KeyEvent;
import java.util.LinkedHashMap;
import java.util.Map;
import java.util.Objects;
import javax.swing.AbstractAction;
import javax.swing.JComponent;
import javax.swing.JTextField;
import javax.swing.KeyStroke;
import net.runelite.client.config.Keybind;
import net.runelite.client.ui.components.IconTextField;

/** Binds palette actions on the text field that actually receives keyboard focus. */
final class PaletteKeyBindings
{
	private static final String HOTKEY_CLOSE_ACTION = "paletteHotkeyClose";
	private final JTextField focusedInput;
	private final Map<KeyStroke, Object> replacedBindings = new LinkedHashMap<>();

	private PaletteKeyBindings(JTextField focusedInput, Runnable close)
	{
		this.focusedInput = focusedInput;
		focusedInput.getActionMap().put(HOTKEY_CLOSE_ACTION, new AbstractAction()
		{
			@Override
			public void actionPerformed(ActionEvent event)
			{
				close.run();
			}
		});
	}

	static PaletteKeyBindings install(IconTextField searchField, Runnable down, Runnable up,
		Runnable confirm, Runnable close)
	{
		JTextField focusedInput = findTextInput(Objects.requireNonNull(searchField, "searchField"));
		if (focusedInput == null)
		{
			throw new IllegalStateException("IconTextField has no focused text input");
		}
		bind(focusedInput, KeyEvent.VK_DOWN, "paletteDown", down);
		bind(focusedInput, KeyEvent.VK_UP, "paletteUp", up);
		bind(focusedInput, KeyEvent.VK_ENTER, "paletteEnter", confirm);
		bind(focusedInput, KeyEvent.VK_ESCAPE, "paletteEscape", close);
		return new PaletteKeyBindings(focusedInput, close);
	}

	void updateHotkey(Keybind keybind)
	{
		for (Map.Entry<KeyStroke, Object> binding : replacedBindings.entrySet())
		{
			KeyStroke stroke = binding.getKey();
			if (HOTKEY_CLOSE_ACTION.equals(focusedInput.getInputMap(JComponent.WHEN_FOCUSED).get(stroke)))
			{
				if (binding.getValue() == null)
				{
					focusedInput.getInputMap(JComponent.WHEN_FOCUSED).remove(stroke);
				}
				else
				{
					focusedInput.getInputMap(JComponent.WHEN_FOCUSED).put(stroke, binding.getValue());
				}
			}
		}
		replacedBindings.clear();
		if (keybind == null || Keybind.NOT_SET.equals(keybind))
		{
			return;
		}
		int code = keybind.getKeyCode();
		int modifiers = keybind.getModifiers();
		if (code != KeyEvent.VK_UNDEFINED)
		{
			addCloseStroke(code, modifiers);
			return;
		}
		// RuneLite also permits modifier-only keybinds. Any final modifier can complete one.
		if ((modifiers & InputEvent.CTRL_DOWN_MASK) != 0)
		{
			addCloseStroke(KeyEvent.VK_CONTROL, modifiers);
		}
		if ((modifiers & InputEvent.ALT_DOWN_MASK) != 0)
		{
			addCloseStroke(KeyEvent.VK_ALT, modifiers);
		}
		if ((modifiers & InputEvent.SHIFT_DOWN_MASK) != 0)
		{
			addCloseStroke(KeyEvent.VK_SHIFT, modifiers);
		}
		if ((modifiers & InputEvent.META_DOWN_MASK) != 0)
		{
			addCloseStroke(KeyEvent.VK_META, modifiers);
		}
	}

	private void addCloseStroke(int code, int modifiers)
	{
		KeyStroke stroke = KeyStroke.getKeyStroke(code, modifiers);
		replacedBindings.put(stroke, focusedInput.getInputMap(JComponent.WHEN_FOCUSED).get(stroke));
		focusedInput.getInputMap(JComponent.WHEN_FOCUSED).put(stroke, HOTKEY_CLOSE_ACTION);
	}

	static JTextField findTextInput(Component component)
	{
		if (component instanceof JTextField)
		{
			return (JTextField) component;
		}
		if (component instanceof Container)
		{
			for (Component child : ((Container) component).getComponents())
			{
				JTextField found = findTextInput(child);
				if (found != null)
				{
					return found;
				}
			}
		}
		return null;
	}

	private static void bind(JTextField input, int keyCode, String actionKey, Runnable action)
	{
		Objects.requireNonNull(action, actionKey);
		input.getInputMap(JComponent.WHEN_FOCUSED).put(KeyStroke.getKeyStroke(keyCode, 0), actionKey);
		input.getActionMap().put(actionKey, new AbstractAction()
		{
			@Override
			public void actionPerformed(ActionEvent event)
			{
				action.run();
			}
		});
	}
}

package com.example.palette;

import java.awt.Dimension;
import java.awt.GraphicsConfiguration;
import java.awt.GraphicsEnvironment;
import java.awt.Insets;
import java.awt.Rectangle;
import java.awt.Toolkit;
import java.awt.Window;

public final class PalettePositioning
{
	private PalettePositioning()
	{
	}

	/** Centre horizontally; place the dialog centre one third down the usable monitor. */
	public static Rectangle boundsFor(Rectangle usable, Dimension preferred)
	{
		int width = Math.min(Math.max(1, preferred.width), usable.width);
		int height = Math.min(Math.max(1, preferred.height), usable.height);
		int x = usable.x + (usable.width - width) / 2;
		int y = usable.y + usable.height / 3 - height / 2;
		y = Math.max(usable.y, Math.min(y, usable.y + usable.height - height));
		return new Rectangle(x, y, width, height);
	}

	/** Uses the RuneLite owner's monitor and excludes taskbar or dock insets. */
	public static Rectangle usableBounds(Window owner)
	{
		GraphicsConfiguration screen = owner.getGraphicsConfiguration();
		if (screen == null)
		{
			screen = GraphicsEnvironment.getLocalGraphicsEnvironment()
				.getDefaultScreenDevice().getDefaultConfiguration();
		}
		Rectangle bounds = screen.getBounds();
		Insets insets = Toolkit.getDefaultToolkit().getScreenInsets(screen);
		return new Rectangle(bounds.x + insets.left, bounds.y + insets.top,
			bounds.width - insets.left - insets.right,
			bounds.height - insets.top - insets.bottom);
	}
}

