public class TakeMeTherePanel extends PluginPanel
{
	private static final String FAVOURITES_CATEGORY_ID = "favourites";
	private static final String FAVOURITES_DISPLAY_NAME = "Favourites";

	private static final String CUSTOM_CATEGORY_ID = "custom";
	private static final String CUSTOM_CATEGORY_NAME = "Custom Locations";

	private static final String STAR_ON = "\u2605";
	private static final String STAR_OFF = "\u2606";
	private static final int STAR_HIT_WIDTH_PX = 26;
	private static final int STAR_RIGHT_PADDING_PX = 8;

	private final IconTextField searchField = new PlaceholderIconTextField("Search");
	private final JLabel paletteTip = new JLabel("Tip: Ctrl+T for quick search");
	private final JTree tree = new JTree();

	private final JButton manageButton = new JButton("Manage Custom Locations");

	private final Map<String, Boolean> expandedByCategoryId = new LinkedHashMap<>();

	private final LocationCatalog catalog;
	private final SearchService searchService;
	private final List<SearchCandidate> builtInCandidates = new ArrayList<>();
	private final FavouritesStore favouritesStore;
	private final DestinationSelectionService selectionService;
	private final LinkedHashSet<String> favouriteIds = new LinkedHashSet<>();

	private final CustomLocationsStore customLocationsStore;
	private CustomLocationsManagerDialog customLocationsDialog;

	private final Map<String, CustomLocation> customLocationsById = new LinkedHashMap<>();

	public TakeMeTherePanel(LocationCatalog catalog)
	{
		this(catalog, null, null, null);
	}

	public TakeMeTherePanel(LocationCatalog catalog, FavouritesStore favouritesStore)
	{
		this(catalog, favouritesStore, null, null);
	}

	public TakeMeTherePanel(LocationCatalog catalog, FavouritesStore favouritesStore, DestinationService destinationService)
	{
		this(catalog, favouritesStore, destinationService, null);
	}

	public TakeMeTherePanel(
		LocationCatalog catalog,
		FavouritesStore favouritesStore,
		DestinationService destinationService,
		CustomLocationsStore customLocationsStore)
	{
		this(catalog, favouritesStore, destinationService, customLocationsStore, new SearchService());
	}

	public TakeMeTherePanel(
		LocationCatalog catalog,
		FavouritesStore favouritesStore,
		DestinationService destinationService,
		CustomLocationsStore customLocationsStore,
		SearchService searchService)
	{
		this(catalog, favouritesStore, customLocationsStore, searchService,
			destinationService == null ? null : new DestinationSelectionService(destinationService, null));
	}

	public TakeMeTherePanel(
		LocationCatalog catalog,
		FavouritesStore favouritesStore,
		CustomLocationsStore customLocationsStore,
		SearchService searchService,
		DestinationSelectionService selectionService)
	{
		this.catalog = catalog;
		this.searchService = searchService;
		this.favouritesStore = favouritesStore;
		this.selectionService = selectionService;
		this.customLocationsStore = customLocationsStore;
		for (CategoryDefinition category : catalog.getCategories())
		{
			for (LocationDefinition location : catalog.getLocationsByCategoryId().getOrDefault(category.getId(), List.of()))
			{
				builtInCandidates.add(new SearchCandidate(location.getId(), location.getName(), category.getDisplayName()));
			}
		}

		setLayout(new BorderLayout());
		setBackground(ColorScheme.DARK_GRAY_COLOR);

		expandedByCategoryId.put(FAVOURITES_CATEGORY_ID, false);
		expandedByCategoryId.put(CUSTOM_CATEGORY_ID, false);

		for (CategoryDefinition c : catalog.getCategories())
		{
			expandedByCategoryId.putIfAbsent(c.getId(), false);
		}

		if (favouritesStore != null)
		{
			favouriteIds.addAll(favouritesStore.load());
		}

		add(buildHeader(), BorderLayout.NORTH);
		add(buildTree(), BorderLayout.CENTER);

		searchField.getDocument().addDocumentListener(new DocumentListener()
		{
			@Override public void insertUpdate(DocumentEvent e) { rebuildTree(); }
			@Override public void removeUpdate(DocumentEvent e) { rebuildTree(); }
			@Override public void changedUpdate(DocumentEvent e) { rebuildTree(); }
		});
		searchField.addClearListener(this::rebuildTree);

		rebuildTree();
	}

	private JComponent buildHeader()
	{
		JPanel header = new JPanel();
		header.setLayout(new BoxLayout(header, BoxLayout.Y_AXIS));
		header.setBorder(new EmptyBorder(10, 10, 10, 10));
		header.setBackground(ColorScheme.DARK_GRAY_COLOR);

		JLabel title = new JLabel("Take Me There");
		title.setForeground(Color.WHITE);
		title.setFont(FontManager.getRunescapeBoldFont().deriveFont(16f));
		title.setAlignmentX(Component.CENTER_ALIGNMENT);

		JLabel subtitle = new JLabel("Click to set a destination");
		subtitle.setForeground(ColorScheme.LIGHT_GRAY_COLOR);
		subtitle.setFont(FontManager.getRunescapeFont().deriveFont(12f));
		subtitle.setAlignmentX(Component.CENTER_ALIGNMENT);

		// IconTextField resolves enum icons relative to getClass(); the hint subclass has a different package.
		searchField.setIcon(new ImageIcon(IconTextField.class.getResource(IconTextField.Icon.SEARCH.getFile())));
		searchField.setBackground(ColorScheme.DARKER_GRAY_COLOR);
		searchField.setHoverBackgroundColor(ColorScheme.DARKER_GRAY_HOVER_COLOR);
		paletteTip.setForeground(ColorScheme.LIGHT_GRAY_COLOR);
		paletteTip.setFont(FontManager.getRunescapeFont().deriveFont(11f));
		paletteTip.setAlignmentX(Component.LEFT_ALIGNMENT);
		paletteTip.setBorder(new EmptyBorder(4, 0, 0, 0));
		paletteTip.setVisible(false);

		configureManageButton();

		header.add(title);
		header.add(Box.createVerticalStrut(4));
		header.add(subtitle);
		header.add(Box.createVerticalStrut(10));
		header.add(manageButton);
		header.add(Box.createVerticalStrut(8));
		header.add(searchField);
		header.add(paletteTip);

		return header;
	}

	public void setPaletteTipVisible(boolean visible)
	{
		paletteTip.setVisible(visible);
		paletteTip.revalidate();
		paletteTip.repaint();
	}

	boolean isPaletteTipVisible()
	{
		return paletteTip.isVisible();
	}

	private void configureManageButton()
	{
		manageButton.setFocusable(false);
		manageButton.setToolTipText("Add, edit, and delete custom locations");
		manageButton.setBackground(ColorScheme.DARKER_GRAY_COLOR);
		manageButton.setForeground(Color.WHITE);
		manageButton.setAlignmentX(Component.CENTER_ALIGNMENT);

		manageButton.setEnabled(customLocationsStore != null);

		for (var listener : manageButton.getActionListeners())
		{
			manageButton.removeActionListener(listener);
		}

		manageButton.addActionListener(e -> SwingUtilities.invokeLater(this::showCustomLocationsDialog));
	}

	private void showCustomLocationsDialog()
	{
		if (customLocationsStore == null)
		{
			return;
		}

		if (customLocationsDialog == null)
		{
			Window owner = SwingUtilities.getWindowAncestor(this);
			customLocationsDialog = new CustomLocationsManagerDialog(owner, customLocationsStore);

			customLocationsDialog.addComponentListener(new ComponentAdapter()
			{
				@Override
				public void componentHidden(java.awt.event.ComponentEvent e)
				{
					SwingUtilities.invokeLater(TakeMeTherePanel.this::rebuildTree);
				}
			});
		}

		customLocationsDialog.setVisible(true);
		customLocationsDialog.toFront();
		customLocationsDialog.requestFocus();
	}

	private JComponent buildTree()
	{
		tree.setRootVisible(false);
		tree.setShowsRootHandles(false);
		tree.setRowHeight(22);
		tree.setBackground(ColorScheme.DARK_GRAY_COLOR);
		tree.setCellRenderer(new TakeMeThereTreeCellRenderer());
		tree.setToggleClickCount(0);

		tree.addTreeExpansionListener(new javax.swing.event.TreeExpansionListener()
		{
			@Override
			public void treeExpanded(javax.swing.event.TreeExpansionEvent event)
			{
				updateExpansionStateFromEvent(event, true);
			}

			@Override
			public void treeCollapsed(javax.swing.event.TreeExpansionEvent event)
			{
				updateExpansionStateFromEvent(event, false);
			}
		});

		tree.addMouseListener(new MouseAdapter()
		{
			@Override
			public void mousePressed(MouseEvent e)
			{
				TreePath path = tree.getPathForLocation(e.getX(), e.getY());
				if (path == null)
				{
					return;
				}

				DefaultMutableTreeNode node = (DefaultMutableTreeNode) path.getLastPathComponent();
				Object userObject = node.getUserObject();

				if (!SwingUtilities.isLeftMouseButton(e))
				{
					return;
				}

				if (userObject instanceof CategoryDefinition)
				{
					toggleCategory(path);
					tree.clearSelection();
					return;
				}

				if (userObject instanceof LocationDefinition)
				{
					LocationDefinition location = (LocationDefinition) userObject;

					if (isStarClick(path, e))
					{
						toggleFavourite(location.getId());
						tree.clearSelection();
						return;
					}

					setDestination(location.getId(), location.getX(), location.getY(), location.getPlane());
					tree.clearSelection();
					return;
				}

				if (userObject instanceof CustomLocation)
				{
					CustomLocation location = (CustomLocation) userObject;

					if (isStarClick(path, e))
					{
						toggleFavourite(location.getId());
						tree.clearSelection();
						return;
					}

					setDestination(location.getId(), location.getX(), location.getY(), location.getPlane());
					tree.clearSelection();
				}
			}
		});

		JScrollPane scrollPane = new JScrollPane(tree);
		scrollPane.setBorder(null);
		return scrollPane;
	}

	private void toggleCategory(TreePath path)
	{
		if (tree.isExpanded(path))
		{
			tree.collapsePath(path);
		}
		else
		{
			tree.expandPath(path);
		}
	}

	private boolean isStarClick(TreePath path, MouseEvent e)
	{
		Rectangle bounds = tree.getPathBounds(path);
		if (bounds == null)
		{
			return false;
		}

		int starHitLeft = bounds.x + bounds.width - STAR_HIT_WIDTH_PX - STAR_RIGHT_PADDING_PX;
		return e.getX() >= starHitLeft;
	}

	private void toggleFavourite(String id)
	{
		if (favouritesStore == null)
		{
			return;
		}

		if (favouriteIds.contains(id))
		{
			favouriteIds.remove(id);
			favouritesStore.remove(id);
		}
		else
		{
			favouriteIds.add(id);
			favouritesStore.add(id);
		}

		rebuildTree();
	}

	private void setDestination(String id, int x, int y, int plane)
	{
		if (selectionService == null)
		{
			return;
		}

		selectionService.select(id, new WorldPoint(x, y, plane), searchField.getText());
	}

	private void reloadCustomLocations()
	{
		customLocationsById.clear();

		if (customLocationsStore == null)
		{
			return;
		}

		for (CustomLocation l : customLocationsStore.load())
		{
			if (l != null)
			{
				customLocationsById.put(l.getId(), l);
			}
		}
	}

	private void rebuildTree()
	{
		reloadCustomLocations();

		String query = SearchService.normalize(searchField.getText());
		boolean searching = !query.isEmpty();
		Set<String> matchingIds = new HashSet<>();
		if (searching)
		{
			List<SearchCandidate> candidates = new ArrayList<>(builtInCandidates);
			for (CustomLocation location : customLocationsById.values())
			{
				candidates.add(new SearchCandidate(location.getId(), location.getName(), CUSTOM_CATEGORY_NAME));
			}
			for (SearchResult result : searchService.search(query, candidates))
			{
				matchingIds.add(result.getId());
			}
		}

		DefaultMutableTreeNode root = new DefaultMutableTreeNode("root");

		DefaultMutableTreeNode favouritesNode = buildFavouritesNode(matchingIds, searching);
		if (favouritesNode != null)
		{
			root.add(favouritesNode);
		}

		DefaultMutableTreeNode customNode = buildCustomLocationsNode(matchingIds, searching);
		if (customNode != null)
		{
			root.add(customNode);
		}

		for (CategoryDefinition category : catalog.getCategories())
		{
			DefaultMutableTreeNode catNode = new DefaultMutableTreeNode(category);

			List<LocationDefinition> locations = catalog.getLocationsByCategoryId()
				.getOrDefault(category.getId(), List.of());

			for (LocationDefinition location : locations)
			{
				if (searching && !matchingIds.contains(location.getId()))
				{
					continue;
				}
				catNode.add(new DefaultMutableTreeNode(location));
			}

			if (searching)
			{
				if (catNode.getChildCount() > 0)
				{
					root.add(catNode);
				}
			}
			else
			{
				root.add(catNode);
			}
		}

		tree.setModel(new DefaultTreeModel(root));

		if (searching)
		{
			expandAll();
		}
		else
		{
			applySavedExpansionState();
		}
	}

	private DefaultMutableTreeNode buildCustomLocationsNode(Set<String> matchingIds, boolean searching)
	{
		DefaultMutableTreeNode customNode = new DefaultMutableTreeNode(
			new CategoryDefinition(CUSTOM_CATEGORY_ID, CUSTOM_CATEGORY_NAME)
		);

		for (CustomLocation l : customLocationsById.values())
		{
			if (searching && !matchingIds.contains(l.getId()))
			{
				continue;
			}
			customNode.add(new DefaultMutableTreeNode(l));
		}

		if (searching)
		{
			return customNode.getChildCount() == 0 ? null : customNode;
		}

		return customNode;
	}

	private DefaultMutableTreeNode buildFavouritesNode(Set<String> matchingIds, boolean searching)
	{
		DefaultMutableTreeNode favNode = new DefaultMutableTreeNode(
			new CategoryDefinition(FAVOURITES_CATEGORY_ID, FAVOURITES_DISPLAY_NAME)
		);

		for (String favId : favouriteIds)
		{
			LocationDefinition builtIn = catalog.getLocationsById().get(favId);
			if (builtIn != null)
			{
				if (!searching || matchingIds.contains(builtIn.getId()))
				{
					favNode.add(new DefaultMutableTreeNode(builtIn));
				}
				continue;
			}

			CustomLocation custom = customLocationsById.get(favId);
			if (custom != null)
			{
				if (!searching || matchingIds.contains(custom.getId()))
				{
					favNode.add(new DefaultMutableTreeNode(custom));
				}
			}
		}

		if (searching)
		{
			return favNode.getChildCount() == 0 ? null : favNode;
		}

		return favNode;
	}

	private void applySavedExpansionState()
	{
		Object rootObj = tree.getModel().getRoot();
		if (!(rootObj instanceof DefaultMutableTreeNode))
		{
			return;
		}

		DefaultMutableTreeNode root = (DefaultMutableTreeNode) rootObj;

		for (int i = 0; i < root.getChildCount(); i++)
		{
			DefaultMutableTreeNode catNode = (DefaultMutableTreeNode) root.getChildAt(i);
			Object userObject = catNode.getUserObject();
			if (!(userObject instanceof CategoryDefinition))
			{
				continue;
			}

			CategoryDefinition category = (CategoryDefinition) userObject;
			boolean expanded = expandedByCategoryId.getOrDefault(category.getId(), false);

			TreePath path = new TreePath(catNode.getPath());
			if (expanded)
			{
				tree.expandPath(path);
			}
			else
			{
				tree.collapsePath(path);
			}
		}
	}

	private void expandAll()
	{
		for (int i = 0; i < tree.getRowCount(); i++)
		{
			tree.expandRow(i);
		}
	}

	private void updateExpansionStateFromEvent(javax.swing.event.TreeExpansionEvent event, boolean expanded)
	{
		String query = SearchService.normalize(searchField.getText());
		if (!query.isEmpty())
		{
			return;
		}

		Object last = event.getPath().getLastPathComponent();
		if (!(last instanceof DefaultMutableTreeNode))
		{
			return;
		}

		DefaultMutableTreeNode node = (DefaultMutableTreeNode) last;
		Object userObject = node.getUserObject();
		if (userObject instanceof CategoryDefinition)
		{
			expandedByCategoryId.put(((CategoryDefinition) userObject).getId(), expanded);
			tree.repaint();
		}
	}

	private final class TakeMeThereTreeCellRenderer extends JPanel implements javax.swing.tree.TreeCellRenderer
	{
		private final JLabel textLabel = new JLabel();
		private final JLabel starLabel = new JLabel();

		private TakeMeThereTreeCellRenderer()
		{
			setLayout(new BorderLayout());
			setOpaque(true);

			textLabel.setOpaque(false);

			starLabel.setOpaque(false);
			starLabel.setHorizontalAlignment(SwingConstants.RIGHT);
			starLabel.setPreferredSize(new Dimension(STAR_HIT_WIDTH_PX, 0));

			add(textLabel, BorderLayout.CENTER);
			add(starLabel, BorderLayout.EAST);
		}

		@Override
		public Component getTreeCellRendererComponent(
			JTree tree,
			Object value,
			boolean selected,
			boolean expanded,
			boolean leaf,
			int row,
			boolean hasFocus)
		{
			Object userObject = extractUserObject(value);

			setBackground(ColorScheme.DARK_GRAY_COLOR);

			textLabel.setForeground(Color.WHITE);
			starLabel.setForeground(ColorScheme.LIGHT_GRAY_COLOR);

			starLabel.setVisible(false);
			starLabel.setText("");

			if (userObject instanceof CategoryDefinition)
			{
				setBorder(new EmptyBorder(2, 6, 2, 6));

				CategoryDefinition category = (CategoryDefinition) userObject;
				String prefix = expanded ? "- " : "+ ";
				textLabel.setText(prefix + category.getDisplayName());
				textLabel.setFont(FontManager.getRunescapeBoldFont().deriveFont(13f));
			}
			else if (userObject instanceof LocationDefinition)
			{
				setBorder(new EmptyBorder(2, 18, 2, 6));

				LocationDefinition location = (LocationDefinition) userObject;
				textLabel.setText(location.getName());
				textLabel.setFont(FontManager.getRunescapeFont().deriveFont(12f));

				starLabel.setVisible(true);
				boolean isFav = favouriteIds.contains(location.getId());
				starLabel.setText(isFav ? STAR_ON : STAR_OFF);
				starLabel.setForeground(isFav ? Color.WHITE : ColorScheme.LIGHT_GRAY_COLOR);
			}
			else if (userObject instanceof CustomLocation)
			{
				setBorder(new EmptyBorder(2, 18, 2, 6));

				CustomLocation location = (CustomLocation) userObject;
				textLabel.setText(location.getName());
				textLabel.setFont(FontManager.getRunescapeFont().deriveFont(12f));

				starLabel.setVisible(true);
				boolean isFav = favouriteIds.contains(location.getId());
				starLabel.setText(isFav ? STAR_ON : STAR_OFF);
				starLabel.setForeground(isFav ? Color.WHITE : ColorScheme.LIGHT_GRAY_COLOR);
			}
			else
			{
				setBorder(new EmptyBorder(2, 6, 2, 6));
				textLabel.setText(String.valueOf(userObject));
				textLabel.setFont(FontManager.getRunescapeFont().deriveFont(12f));
			}

			return this;
		}

		private Object extractUserObject(Object value)
		{
			if (value instanceof DefaultMutableTreeNode)
			{
				return ((DefaultMutableTreeNode) value).getUserObject();
			}
			return value;
		}
	}
}

package com.example;

import com.example.data.LocationCatalogLoader;
import com.example.model.LocationCatalog;
import com.google.gson.Gson;
import com.google.gson.JsonArray;
import com.google.gson.JsonElement;
import com.google.gson.JsonObject;
import com.google.gson.JsonParser;
import org.junit.Test;

import java.io.InputStream;
import java.io.InputStreamReader;
import java.io.Reader;
import java.nio.charset.StandardCharsets;
import java.util.HashSet;
import java.util.Locale;
import java.util.Set;

import static org.junit.Assert.*;

public class CatalogIntegrityTest
{
	private static final String BASE_PATH = "/takemethere/";

	@Test
	public void allReferencedCatalogsAreValid() throws Exception
	{
		JsonArray categories = readArray("categories.json");
		assertFalse("No categories", categories.size() == 0);

		Set<String> categoryIds = new HashSet<>();
		Set<String> locationIds = new HashSet<>();
		for (JsonElement element : categories)
		{
			JsonObject category = element.getAsJsonObject();
			assertEquals(Set.of("id", "displayName"), category.keySet());
			String categoryId = requiredString(category, "id");
			assertTrue("Invalid category ID: " + categoryId, categoryId.matches("[a-z0-9-]+"));
			assertTrue("Duplicate category ID: " + categoryId, categoryIds.add(categoryId));
			requiredString(category, "displayName");

			JsonArray locations = readArray(categoryId + ".json");
			assertTrue("Empty category: " + categoryId, locations.size() > 0);
			Set<String> visibleNames = new HashSet<>();
			for (JsonElement locationElement : locations)
			{
				JsonObject location = locationElement.getAsJsonObject();
				assertEquals(categoryId + " has unexpected or missing fields",
					Set.of("id", "name", "x", "y", "plane"), location.keySet());
				String id = requiredString(location, "id");
				assertTrue("Location ID has wrong category: " + id,
					id.startsWith(categoryId + ":") && id.length() > categoryId.length() + 1);
				assertTrue("Duplicate location ID: " + id, locationIds.add(id));
				String name = requiredString(location, "name");
				assertTrue("Duplicate visible name in " + categoryId + ": " + name,
					visibleNames.add(name.trim().toLowerCase(Locale.ROOT)));
				int x = requiredInt(location, "x");
				int y = requiredInt(location, "y");
				int plane = requiredInt(location, "plane");
				assertTrue(id + " has invalid x", x >= 1000 && x <= 5000);
				assertTrue(id + " has invalid y", y >= 2000 && y <= 16000);
				assertTrue(id + " has invalid plane", plane >= 0 && plane <= 3);
			}
		}

		LocationCatalog loaded = new LocationCatalogLoader(new Gson()).load();
		assertEquals(categoryIds.size(), loaded.getCategories().size());
		assertEquals(locationIds.size(), loaded.getLocationsById().size());
	}

	private static JsonArray readArray(String filename) throws Exception
	{
		String path = BASE_PATH + filename;
		InputStream stream = CatalogIntegrityTest.class.getResourceAsStream(path);
		assertNotNull("Missing catalog resource: " + path, stream);
		try (Reader reader = new InputStreamReader(stream, StandardCharsets.UTF_8))
		{
			JsonElement parsed = new JsonParser().parse(reader);
			assertTrue("Expected JSON array: " + path, parsed.isJsonArray());
			return parsed.getAsJsonArray();
		}
	}

	private static String requiredString(JsonObject object, String field)
	{
		JsonElement value = object.get(field);
		assertNotNull("Missing " + field, value);
		assertTrue("Expected string: " + field, value.isJsonPrimitive() && value.getAsJsonPrimitive().isString());
		String text = value.getAsString();
		assertFalse("Blank " + field, text.trim().isEmpty());
		return text;
	}

	private static int requiredInt(JsonObject object, String field)
	{
		JsonElement value = object.get(field);
		assertNotNull("Missing " + field, value);
		assertTrue("Expected integer: " + field,
			value.isJsonPrimitive() && value.getAsJsonPrimitive().isNumber()
				&& value.getAsString().matches("-?[0-9]+"));
		return value.getAsInt();
	}
}

package com.example;

import net.runelite.api.Client;
import net.runelite.api.Player;
import net.runelite.api.coords.WorldPoint;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.eventbus.EventBus;
import net.runelite.client.events.PluginMessage;
import org.junit.Test;

import java.lang.reflect.Proxy;
import java.util.ArrayList;
import java.util.List;
import java.util.Map;

import static org.junit.Assert.*;

public class DestinationServiceTest
{
	@Test
	public void postsShortestPathMessageAfterReadingPlayerOnClientThread()
	{
		WorldPoint start = new WorldPoint(3221, 3218, 0);
		WorldPoint target = new WorldPoint(3165, 3490, 0);
		int[] playerReads = {0};
		int[] locationReads = {0};
		Player player = proxy(Player.class, (proxy, method, args) ->
		{
			if (method.getName().equals("getWorldLocation"))
			{
				locationReads[0]++;
				return start;
			}
			throw new AssertionError("Unexpected Player call: " + method.getName());
		});
		Client client = proxy(Client.class, (proxy, method, args) ->
		{
			if (method.getName().equals("getLocalPlayer"))
			{
				playerReads[0]++;
				return player;
			}
			throw new AssertionError("Unexpected Client call: " + method.getName());
		});
		RecordingClientThread clientThread = new RecordingClientThread();
		RecordingEventBus eventBus = new RecordingEventBus();
		new DestinationService(client, clientThread, eventBus).setDestination(target);

		assertEquals(0, playerReads[0]);
		assertEquals(0, locationReads[0]);
		assertTrue(eventBus.events.isEmpty());
		assertNotNull("Client thread was not scheduled", clientThread.pending);

		clientThread.runPending();
		assertEquals(1, playerReads[0]);
		assertTrue(locationReads[0] > 0);
		assertEquals(1, eventBus.events.size());
		PluginMessage message = (PluginMessage) eventBus.events.get(0);
		assertEquals("shortestpath", message.getNamespace());
		assertEquals("path", message.getName());
		assertEquals(Map.of("start", start, "target", target), message.getData());
	}

	@Test
	public void nullPlayerDoesNotPostDestination()
	{
		Client client = proxy(Client.class, (proxy, method, args) ->
		{
			if (method.getName().equals("getLocalPlayer"))
			{
				return null;
			}
			throw new AssertionError("Unexpected Client call: " + method.getName());
		});
		RecordingClientThread clientThread = new RecordingClientThread();
		RecordingEventBus eventBus = new RecordingEventBus();
		new DestinationService(client, clientThread, eventBus).setDestination(new WorldPoint(3165, 3490, 0));
		clientThread.runPending();
		assertTrue(eventBus.events.isEmpty());
	}

	@Test
	public void nullTargetDoesNotScheduleClientThread()
	{
		RecordingClientThread clientThread = new RecordingClientThread();
		RecordingEventBus eventBus = new RecordingEventBus();
		new DestinationService(null, clientThread, eventBus).setDestination(null);
		assertNull(clientThread.pending);
		assertTrue(eventBus.events.isEmpty());
	}

	private static <T> T proxy(Class<T> type, java.lang.reflect.InvocationHandler handler)
	{
		return type.cast(Proxy.newProxyInstance(type.getClassLoader(), new Class<?>[]{type}, handler));
	}

	private static final class RecordingClientThread extends ClientThread
	{
		private Runnable pending;

		@Override
		public void invokeLater(Runnable runnable)
		{
			assertNull("Unexpected second client-thread task", pending);
			pending = runnable;
		}

		private void runPending()
		{
			assertNotNull("No client-thread task", pending);
			Runnable runnable = pending;
			pending = null;
			runnable.run();
		}
	}

	private static final class RecordingEventBus extends EventBus
	{
		private final List<Object> events = new ArrayList<>();

		@Override
		public void post(Object event)
		{
			events.add(event);
		}
	}
}

