	}

	@Test
	public void searchUsesRankingAndNormalizedQueryThenClearingRestoresLast()
	{
		history.recordSelection("b", "magic");
		history.recordSelection("a", "");
		DestinationPaletteController controller = controller();
		controller.open();
		controller.queryChanged("  MAGIC!!!  ");
		assertEquals("magic", controller.getQuery());
		assertEquals("b", controller.getVisible().get(0).getId());
		assertEquals(0, controller.getSelectedIndex());
		controller.moveSelection(1);
		assertEquals(1, controller.getSelectedIndex());
		controller.moveSelection(-1);
		assertEquals(0, controller.getSelectedIndex());
		controller.queryChanged("Sawmill");
		assertEquals("c", controller.getVisible().get(0).getId());
		assertEquals(0, controller.getSelectedIndex());
		controller.queryChanged(" ");
		assertEquals("a", controller.getVisible().get(0).getId());
		assertEquals(0, controller.getSelectedIndex());
		assertFalse(controller.hasMovedSelection());
	}

	@Test
	public void searchSelectionSupportsCustomIdAndClosesOnlyAfterSuccessfulCompletion()
	{
		DestinationPaletteController controller = controller();
		controller.open();
		controller.queryChanged("my magic shop");
		controller.confirm();
		controller.confirm(); // pending request cannot dispatch twice
		assertEquals(1, selections.size());
		assertEquals("custom:uuid", selections.get(0).destination.getId());
		assertEquals("my magic shop", selections.get(0).query);
		selections.get(0).complete.accept(false);
		assertTrue(controller.isOpen());
		assertEquals(0, closes);
		controller.confirm();
		assertEquals(2, selections.size());
		selections.get(1).complete.accept(true);
		assertFalse(controller.isOpen());
		assertEquals(1, closes);
	}

	@Test
	public void noResultEscapeAndMouseSelectionAreSafe()
	{
		DestinationPaletteController controller = controller();
		controller.open();
		controller.queryChanged("totally unrelated destination");
		assertTrue(controller.getVisible().isEmpty());
		controller.moveSelection(1);
		controller.confirm();
		assertTrue(selections.isEmpty());
		controller.queryChanged("magic");
		controller.selectIndex(1); // same action the dialog uses for a mouse click
		controller.confirm(); // same action the dialog uses for a double-click
		assertEquals(1, selections.size());
		assertEquals("b", selections.get(0).destination.getId());
		selections.get(0).complete.accept(false);
		controller.closeWithoutSelection();
		assertEquals(1, closes);
		assertEquals(1, selections.size());
	}

	@Test
	public void suggestionsAreCappedAndEqualGlobalCountsUseNameThenId()
	{
		List<PaletteDestination> many = new ArrayList<>();
		for (int i = 12; i >= 0; i--)
		{
			many.add(destination(String.format("id%02d", i), "Place"));
			history.recordSelection(String.format("id%02d", i), "");
		}
		destinations = many;
		DestinationPaletteController controller = controller();
		controller.open();
		assertEquals(DestinationPaletteController.VISIBLE_RESULT_LIMIT, controller.getVisible().size());
		assertEquals("id00", controller.getVisible().get(0).getId());
		controller.queryChanged("Place");
		assertEquals(DestinationPaletteController.VISIBLE_RESULT_LIMIT, controller.getVisible().size());
	}

	@Test
	public void globalSuggestionsUseCountThenNameThenStableId()
	{
		config.put("history", "{\"version\":1,\"lastDestinationId\":null,"
			+ "\"globalCounts\":{\"a\":2,\"b\":3,\"c\":3,\"custom:uuid\":3},"
			+ "\"queries\":[],\"recentIds\":[]}");
		LearnedHistoryStore reloaded = new LearnedHistoryStore(
			() -> config.get("history"), value -> config.put("history", value),
			() -> config.remove("history"), new Gson());
		DestinationPaletteController controller = controller(reloaded);
		controller.open();
		assertEquals(List.of("b", "custom:uuid", "c", "a"), ids(controller));
		assertEquals(-1, controller.getSelectedIndex());
	}

	private DestinationPaletteController controller()
	{
		return controller(history);
	}

	private DestinationPaletteController controller(LearnedHistoryStore store)
	{
		SearchService search = new SearchService(new SearchMetadata(Map.of()), store);
		return new DestinationPaletteController(() -> destinations, search, store,
			(destination, query, complete) -> selections.add(new Selection(destination, query, complete)),
			() -> closes++);
	}

	private static PaletteDestination destination(String id, String name)
	{
		return new PaletteDestination(id, name, "Test category", new WorldPoint(3200, 3200, 0));
	}

	private static List<String> ids(DestinationPaletteController controller)
	{
		List<String> ids = new ArrayList<>();
		for (PaletteDestination destination : controller.getVisible()) ids.add(destination.getId());
		return ids;
	}

	private static final class Selection
	{
		private final PaletteDestination destination;
		private final String query;
		private final Consumer<Boolean> complete;

		private Selection(PaletteDestination destination, String query, Consumer<Boolean> complete)
		{
			this.destination = destination;
			this.query = query;
			this.complete = complete;
		}
	}
}

package com.example.history;

import com.example.DestinationSelectionService;
import com.example.DestinationService;
import com.google.gson.Gson;
import net.runelite.api.Client;
import net.runelite.api.Player;
import net.runelite.api.coords.WorldPoint;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.eventbus.EventBus;
import net.runelite.client.events.PluginMessage;
import org.junit.Test;

import java.lang.reflect.Proxy;
import java.util.ArrayList;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import java.util.Set;

import static org.junit.Assert.*;

public class DestinationSelectionServiceTest
{
	private final Map<String, String> config = new HashMap<>();
	private final LearnedHistoryStore history = new LearnedHistoryStore(
		() -> config.get("history"), value -> config.put("history", value), () -> config.remove("history"), new Gson());
	private final RecordingClientThread clientThread = new RecordingClientThread();
	private final RecordingEventBus eventBus = new RecordingEventBus();
	private final List<Runnable> pendingHistory = new ArrayList<>();
	private final WorldPoint target = new WorldPoint(3165, 3490, 0);

	@Test
	public void successfulPathPostRecordsExactlyOnceAndNormalizesQuery()
	{
		DestinationSelectionService selection = selection(playerClient());
		selection.select("custom:uuid", target, "  MAGIC,  SHOP! ");
		assertEquals(0, history.countsFor("magic shop").globalCount("custom:uuid"));
		clientThread.runPending();
		assertEquals(1, eventBus.events.size());
		PluginMessage message = (PluginMessage) eventBus.events.get(0);
		assertEquals("shortestpath", message.getNamespace());
		assertEquals("path", message.getName());
		assertEquals(target, message.getData().get("target"));
		assertEquals(1, pendingHistory.size());
		pendingHistory.remove(0).run();
		assertEquals(1, history.countsFor("magic shop").queryCount("custom:uuid"));
		assertEquals(1, history.countsFor("magic shop").globalCount("custom:uuid"));
		assertEquals("custom:uuid", history.lastDestinationId(Set.of("custom:uuid")));
		assertTrue(pendingHistory.isEmpty());
	}

	@Test
	public void emptyQueryRecordsGlobalLastAndRecentButNoQueryEntry()
	{
		selection(playerClient()).select("built-in:id", target, "  ");
		clientThread.runPending();
		pendingHistory.remove(0).run();
		assertEquals(1, history.countsFor("").globalCount("built-in:id"));
		assertEquals(0, history.countsFor("").queryCount("built-in:id"));
		assertEquals(List.of("built-in:id"), history.recentDestinationIds(Set.of("built-in:id")));
	}

	@Test
	public void invalidSelectionAndAbsentPlayerNeverRecord()
	{
		DestinationSelectionService selection = selection(playerClient());
		List<Boolean> completions = new ArrayList<>();
		selection.select("", target, "query", completions::add);
		selection.select("id", null, "query", completions::add);
		assertNull(clientThread.pending);
		selection(nullPlayerClient()).select("id", target, "query", completions::add);
		clientThread.runPending();
		assertTrue(eventBus.events.isEmpty());
		assertEquals(3, pendingHistory.size());
		while (!pendingHistory.isEmpty()) pendingHistory.remove(0).run();
		assertEquals(List.of(false, false, false), completions);
		assertEquals(0, history.countsFor("query").globalCount("id"));
	}

	@Test
	public void failedMessagePostNeverRecords()
	{
		eventBus.failPost = true;
		List<Boolean> completions = new ArrayList<>();
		selection(playerClient()).select("id", target, "query", completions::add);
		try
		{
			clientThread.runPending();
			fail("Expected event bus failure");
		}
		catch (IllegalStateException expected)
		{
			assertEquals("post failed", expected.getMessage());
		}
		assertEquals(1, pendingHistory.size());
		pendingHistory.remove(0).run();
		assertEquals(List.of(false), completions);
		assertEquals(0, history.countsFor("query").globalCount("id"));
	}

	@Test
	public void successfulSelectionCompletesOnceAfterHistoryIsRecorded()
	{
		List<Boolean> completions = new ArrayList<>();
		selection(playerClient()).select("id", target, "search", posted ->
		{
			assertEquals(1, history.countsFor("search").globalCount("id"));
			completions.add(posted);
		});
		clientThread.runPending();
		assertTrue(completions.isEmpty());
		assertEquals(1, pendingHistory.size());
		pendingHistory.remove(0).run();
		assertEquals(List.of(true), completions);
		assertTrue(pendingHistory.isEmpty());
	}

	private DestinationSelectionService selection(Client client)
	{
		return new DestinationSelectionService(new DestinationService(client, clientThread, eventBus),
			history, pendingHistory::add);
	}

	private static Client playerClient()
	{
		WorldPoint start = new WorldPoint(3221, 3218, 0);
		Player player = proxy(Player.class, (instance, method, args) ->
		{
			if (method.getName().equals("getWorldLocation"))
			{
				return start;
			}
			throw new AssertionError(method.getName());
		});
		return proxy(Client.class, (instance, method, args) ->
		{
			if (method.getName().equals("getLocalPlayer"))
			{
				return player;
			}
			throw new AssertionError(method.getName());
		});
	}

	private static Client nullPlayerClient()
	{
		return proxy(Client.class, (instance, method, args) ->
		{
			if (method.getName().equals("getLocalPlayer"))
			{
				return null;
			}
			throw new AssertionError(method.getName());
		});
	}

	private static <T> T proxy(Class<T> type, java.lang.reflect.InvocationHandler handler)
	{
		return type.cast(Proxy.newProxyInstance(type.getClassLoader(), new Class<?>[]{type}, handler));
	}

	private static final class RecordingClientThread extends ClientThread
	{
		private Runnable pending;

		@Override
		public void invokeLater(Runnable runnable)
		{
			assertNull(pending);
			pending = runnable;
		}

		private void runPending()
		{
			assertNotNull(pending);
			Runnable task = pending;
			pending = null;
			task.run();
		}
	}

	private static final class RecordingEventBus extends EventBus
	{
		private final List<Object> events = new ArrayList<>();
		private boolean failPost;

		@Override
		public void post(Object event)
		{
			if (failPost)
			{
				throw new IllegalStateException("post failed");
			}
			events.add(event);
		}
	}
}

package com.example.history;

import com.google.gson.Gson;
import org.junit.Test;

import java.util.HashMap;
import java.util.List;
import java.util.Map;
import java.util.Set;

import static org.junit.Assert.*;

public class LearnedHistoryStoreTest
{
	private final Gson gson = new Gson();
	private final Map<String, String> config = new HashMap<>();

	@Test
	public void emptyStoreRoundTripLastCountsAndRecents()
	{
		LearnedHistoryStore store = store();
		assertNull(store.lastDestinationId(Set.of("a")));
		assertTrue(store.recentDestinationIds(Set.of("a")).isEmpty());
		assertEquals(0, store.countsFor("magic shop").globalCount("a"));

		store.recordSelection("a", "  MAGIC,   SHOP! ");
		store.recordSelection("b", "magic shop");
		store.recordSelection("a", "");
		LearnedHistoryStore reloaded = store();
		assertEquals("a", reloaded.lastDestinationId(Set.of("a", "b")));
		assertEquals(List.of("a", "b"), reloaded.recentDestinationIds(Set.of("a", "b")));
		assertEquals(2, reloaded.countsFor("magic shop").globalCount("a"));
		assertEquals(1, reloaded.countsFor("MAGIC--SHOP").queryCount("a"));
		assertEquals(1, reloaded.countsFor("magic shop").queryCount("b"));
		assertEquals(0, reloaded.countsFor("").queryCount("a"));
		assertTrue(config.get("learnedSearchHistory").contains("\"version\":1"));
	}

	@Test
	public void queryEvictionUsesPersistedLeastRecentlyUsedOrder()
	{
		LearnedHistoryStore store = store();
		for (int i = 0; i < LearnedHistoryStore.MAX_QUERIES; i++)
		{
			store.recordSelection("id", "query " + i);
		}
		store.recordSelection("id", "query 0");
		store.recordSelection("id", "query 100");
		LearnedHistoryStore reloaded = store();
		assertEquals(2, reloaded.countsFor("query 0").queryCount("id"));
		assertEquals(0, reloaded.countsFor("query 1").queryCount("id"));
		assertEquals(1, reloaded.countsFor("query 100").queryCount("id"));
	}

	@Test
	public void perQueryAndGlobalCapsKeepNewSelectionDeterministically()
	{
		LearnedHistoryStore store = store();
		for (String id : List.of("a", "b", "c", "d", "e", "f"))
		{
			store.recordSelection(id, "same query");
		}
		assertEquals(0, store.countsFor("same query").queryCount("e"));
		assertEquals(1, store.countsFor("same query").queryCount("f"));
		for (int i = 0; i <= LearnedHistoryStore.MAX_GLOBAL; i++)
		{
			store.recordSelection(String.format("global:%03d", i), "");
		}
		assertEquals(0, store.countsFor("").globalCount("global:199"));
		assertEquals(1, store.countsFor("").globalCount("global:200"));
		assertEquals(0, store.countsFor("").queryCount("global:200"));
	}

	@Test
	public void countersSaturateAndRecentIdsStayUniqueAndBounded()
	{
		config.put("learnedSearchHistory", "{\"version\":1,\"lastDestinationId\":\"a\","
			+ "\"globalCounts\":{\"a\":1000000},"
			+ "\"queries\":[{\"query\":\"q\",\"counts\":{\"a\":1000000}}],"
			+ "\"recentIds\":[\"a\"]}");
		LearnedHistoryStore store = store();
		store.recordSelection("a", "q");
		assertEquals(LearnedHistoryStore.MAX_COUNT, store.countsFor("q").queryCount("a"));
		assertEquals(LearnedHistoryStore.MAX_COUNT, store.countsFor("q").globalCount("a"));
		for (int i = 0; i < 25; i++)
		{
			store.recordSelection("recent:" + i, "");
		}
		store.recordSelection("recent:10", "");
		assertEquals(20, store.recentDestinationIds(allRecentIds()).size());
		assertEquals("recent:10", store.recentDestinationIds(allRecentIds()).get(0));
		assertEquals(1, store.recentDestinationIds(allRecentIds()).stream()
			.filter("recent:10"::equals).count());
	}

	@Test
	public void corruptUnknownVersionAndNegativeCountsLoadAsEmptyWithoutOverwriting()
	{
		for (String raw : List.of("{broken", "{\"version\":2,\"lastDestinationId\":null,\"globalCounts\":{},\"queries\":[],\"recentIds\":[]}",
			"{\"version\":1,\"lastDestinationId\":null,\"globalCounts\":{\"a\":-1},\"queries\":[],\"recentIds\":[]}",
			"{\"version\":1}"))
		{
			config.put("learnedSearchHistory", raw);
			LearnedHistoryStore store = store();
			assertNull(store.lastDestinationId(Set.of("a")));
			assertEquals(0, store.countsFor("q").globalCount("a"));
			assertEquals(raw, config.get("learnedSearchHistory"));
		}
	}

	@Test
	public void staleIdsAreHarmlessAndClearOnlyRemovesHistory()
	{
		LearnedHistoryStore store = store();
		store.recordSelection("custom:deleted", "search");
		store.recordSelection("live", "search");
		assertEquals("live", store.lastDestinationId(Set.of("live")));
		assertEquals(List.of("live"), store.recentDestinationIds(Set.of("live")));
		assertEquals(1, store.countsFor("search").queryCount("custom:deleted"));
		config.put("favourites", "keep");
		config.put("customLocations", "keep");
		store.clear();
		assertFalse(config.containsKey("learnedSearchHistory"));
		assertEquals("keep", config.get("favourites"));
		assertEquals("keep", config.get("customLocations"));
		assertNull(store.lastDestinationId(Set.of("live")));
		assertEquals(0, store.countsFor("search").queryCount("live"));
	}

	@Test
	public void oversizedQueryStillUpdatesSelectionWithoutGrowingQueryHistory()
	{
		LearnedHistoryStore store = store();
		String query = "verylong".repeat(30);
		store.recordSelection("id", query);
		assertEquals(1, store.countsFor(query).globalCount("id"));
		assertEquals(0, store.countsFor(query).queryCount("id"));
		assertEquals("id", store.lastDestinationId(Set.of("id")));
	}

	private LearnedHistoryStore store()
	{
		return new LearnedHistoryStore(() -> config.get("learnedSearchHistory"),
			value -> config.put("learnedSearchHistory", value),
			() -> config.remove("learnedSearchHistory"), gson);
	}

	private static Set<String> allRecentIds()
	{
		java.util.Set<String> ids = new java.util.HashSet<>();
		for (int i = 0; i < 25; i++)
		{
			ids.add("recent:" + i);
		}
		return ids;
	}
}

package com.example.history;

import com.example.data.LocationCatalogLoader;
import com.example.model.LocationCatalog;
import com.example.model.LocationDefinition;
import com.example.search.MatchTier;
import com.example.search.SearchCandidate;
import com.example.search.SearchMetadata;
import com.example.search.SearchResult;
import com.example.search.SearchService;
import com.google.gson.Gson;
import org.junit.Test;

import java.util.HashMap;
import java.util.List;
import java.util.Map;
import java.util.stream.Collectors;

import static org.junit.Assert.*;

public class LearnedRankingTest
{
	private final Map<String, String> config = new HashMap<>();
	private final LearnedHistoryStore history = new LearnedHistoryStore(
		() -> config.get("history"), value -> config.put("history", value), () -> config.remove("history"), new Gson());

	@Test
	public void querySpecificSelectionReordersOnlyItsSameTierPeers()
	{
		SearchService search = new SearchService(new SearchMetadata(Map.of()), history);
		List<SearchCandidate> candidates = List.of(
			new SearchCandidate("a", "Magic Shop Alpha"),
			new SearchCandidate("custom:b", "Magic Shop Beta")
		);
		assertEquals(List.of("a", "custom:b"), ids(search.search("magic shop", candidates)));
		history.recordSelection("custom:b", "  MAGIC,  SHOP! ");
		assertEquals(List.of("custom:b", "a"), ids(search.search("magic shop", candidates)));
		assertEquals(List.of("custom:b", "a"), ids(search.search("magic", candidates))); // weaker global tie-break
		history.recordSelection("a", "magic");
		assertEquals(List.of("a", "custom:b"), ids(search.search("magic", candidates)));
		assertEquals(1, history.countsFor("magic shop").queryCount("custom:b"));
	}

	@Test
	public void selectingRunicEmporiumChangesMagicShopTopResultWithinTokenTier()
	{
		Gson gson = new Gson();
		LocationCatalog catalog = new LocationCatalogLoader(gson).load();
		String talId = "varlamore-shops:tal-teklan-rune-shop-magic-shop";
		String runicId = "varlamore-shops:the-runic-emporium-cam-torum-magic-shop";
		LocationDefinition tal = catalog.getLocationsById().get(talId);
		LocationDefinition runic = catalog.getLocationsById().get(runicId);
		SearchService search = new SearchService(SearchMetadata.load(gson, catalog), history);
		List<SearchCandidate> candidates = List.of(
			new SearchCandidate(tal.getId(), tal.getName()),
			new SearchCandidate(runic.getId(), runic.getName())
		);
		assertEquals(List.of(talId, runicId), ids(search.search("magic shop", candidates)));
		history.recordSelection(runicId, " MAGIC   SHOP ");
		List<SearchResult> learned = search.search("magic shop", candidates);
		assertEquals(List.of(runicId, talId), ids(learned));
		assertEquals(MatchTier.TOKEN, learned.get(0).getTier());
	}

	@Test
	public void queryCountBeatsMuchLargerGlobalCountWithinTier()
	{
		SearchService search = new SearchService(new SearchMetadata(Map.of()), history);
		List<SearchCandidate> candidates = List.of(
			new SearchCandidate("a", "Magic Shop Alpha"),
			new SearchCandidate("b", "Magic Shop Beta")
		);
		for (int i = 0; i < 50; i++)
		{
			history.recordSelection("b", "unrelated");
		}
		history.recordSelection("a", "magic shop");
		assertEquals(List.of("a", "b"), ids(search.search("magic shop", candidates)));
		assertEquals(List.of("b", "a"), ids(search.search("magic", candidates)));
	}

	@Test
	public void historyNeverPromotesAliasFuzzyOrCategoryAcrossTiers()
	{
		SearchService search = new SearchService(new SearchMetadata(Map.of("alias", List.of("cox"))), history);
		for (int i = 0; i < 30; i++)
		{
			history.recordSelection("alias", "cox");
			history.recordSelection("fuzzy", "chambers");
			history.recordSelection("category", "magic shop");
		}
		List<SearchResult> cox = search.search("cox", List.of(
			new SearchCandidate("alias", "Chambers of Xeric"), new SearchCandidate("exact", "Cox")));
		assertEquals(List.of("exact", "alias"), ids(cox));
		assertEquals(MatchTier.EXACT, cox.get(0).getTier());

		List<SearchResult> chambers = search.search("chambers", List.of(
			new SearchCandidate("fuzzy", "Chambars"), new SearchCandidate("prefix", "Chambers of Xeric")));
		assertEquals(List.of("prefix", "fuzzy"), ids(chambers));
		assertEquals(MatchTier.FUZZY, chambers.get(1).getTier());

		List<SearchResult> shop = search.search("magic shop", List.of(
			new SearchCandidate("category", "Runic Emporium", "Magic Shop"),
			new SearchCandidate("token", "Magic Guild Shop")));
		assertEquals(List.of("token", "category"), ids(shop));
		assertEquals(MatchTier.CATEGORY, shop.get(1).getTier());
	}

	@Test
	public void emptyHistoryKeepsBaselineOrderAndStaleIdsDoNotAffectResults()
	{
		List<SearchCandidate> candidates = List.of(new SearchCandidate("b", "Chambers of Xeric"),
			new SearchCandidate("a", "Chambers of Xeric"));
		SearchMetadata metadata = new SearchMetadata(Map.of());
		assertEquals(ids(new SearchService(metadata).search("chambers", candidates)),
			ids(new SearchService(metadata, history).search("chambers", candidates)));
		history.recordSelection("removed:id", "chambers");
		assertEquals(List.of("a", "b"), ids(new SearchService(metadata, history).search("chambers", candidates)));
	}

	private static List<String> ids(List<SearchResult> results)
	{
		return results.stream().map(SearchResult::getId).collect(Collectors.toList());
	}
}

