package com.example.palette;

import com.example.onboarding.PaletteTipState;
import java.awt.event.InputEvent;
import java.awt.event.KeyEvent;
import java.util.ArrayList;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import java.util.concurrent.atomic.AtomicReference;
import java.util.function.Consumer;
import javax.swing.JPanel;
import net.runelite.client.config.Keybind;
import net.runelite.client.input.KeyListener;
import org.junit.Test;

import static org.junit.Assert.*;

public class PaletteHotkeyControllerTest
{
	private final JPanel game = new JPanel();
	private final JPanel searchField = new JPanel();
	private final AtomicReference<Keybind> configured = new AtomicReference<>(
		new Keybind(KeyEvent.VK_T, InputEvent.CTRL_DOWN_MASK));
	private final FakePalette palette = new FakePalette();
	private final List<KeyListener> registered = new ArrayList<>();
	private int registerCalls;
	private int unregisterCalls;
	private Consumer<Keybind> onOpened = ignored -> {};

	@Test
	public void globalHotkeyOpensOnceAndIgnoresEventsWhileOpenOrFromDialog()
	{
		PaletteHotkeyController controller = controller();
		controller.start();
		assertEquals(configured.get(), palette.localHotkey);
		registered.get(0).keyPressed(press(game, KeyEvent.VK_T, InputEvent.CTRL_DOWN_MASK));
		assertEquals(1, palette.opens);
		assertTrue(palette.isOpen());
		registered.get(0).keyPressed(press(game, KeyEvent.VK_T, InputEvent.CTRL_DOWN_MASK));
		assertEquals(1, palette.opens);
		assertEquals(0, palette.closes);

		palette.closeLocally();
		registered.get(0).keyPressed(press(searchField, KeyEvent.VK_T, InputEvent.CTRL_DOWN_MASK));
		assertEquals(1, palette.opens); // The same dialog-owned press cannot reopen it.
		assertEquals(1, palette.closes);
		assertEquals(0, palette.routes);
	}

	@Test
	public void remapUpdatesRuneLiteAndLocalBindingWithoutRestart()
	{
		PaletteHotkeyController controller = controller();
		controller.start();
		Keybind remapped = new Keybind(KeyEvent.VK_G, InputEvent.CTRL_DOWN_MASK);
		configured.set(remapped);
		controller.configurationChanged();
		assertEquals(remapped, palette.localHotkey);
		registered.get(0).keyPressed(press(game, KeyEvent.VK_T, InputEvent.CTRL_DOWN_MASK));
		assertEquals(0, palette.opens);
		registered.get(0).keyPressed(press(game, KeyEvent.VK_G, InputEvent.CTRL_DOWN_MASK));
		assertEquals(1, palette.opens);
	}

	@Test
	public void unsetKeybindDisablesGlobalOpeningAndLocalBinding()
	{
		PaletteHotkeyController controller = controller();
		controller.start();
		configured.set(Keybind.NOT_SET);
		controller.configurationChanged();
		assertEquals(Keybind.NOT_SET, palette.localHotkey);
		registered.get(0).keyPressed(press(game, KeyEvent.VK_T, InputEvent.CTRL_DOWN_MASK));
		assertEquals(0, palette.opens);
	}

	@Test
	public void startupShutdownAndReenableRegisterAndDisposeExactlyOnce()
	{
		PaletteHotkeyController first = controller();
		first.start();
		first.start();
		assertEquals(1, registerCalls);
		registered.get(0).keyPressed(press(game, KeyEvent.VK_T, InputEvent.CTRL_DOWN_MASK));
		first.stop();
		first.stop();
		assertEquals(1, unregisterCalls);
		assertEquals(1, palette.disposals);
		assertFalse(palette.isOpen());
		assertTrue(registered.isEmpty());

		PaletteHotkeyController second = controller();
		second.start();
		assertEquals(2, registerCalls);
		assertEquals(1, registered.size());
		registered.get(0).keyPressed(press(game, KeyEvent.VK_T, InputEvent.CTRL_DOWN_MASK));
		assertEquals(2, palette.opens);
		second.stop();
		assertEquals(2, unregisterCalls);
		assertEquals(2, palette.disposals);
	}

	@Test
	public void firstSuccessfulDefaultOpeningDismissesTipWithoutRouting()
	{
		Map<String, String> configValues = new HashMap<>();
		PaletteTipState tip = new PaletteTipState(() -> configValues.get("paletteTipDismissed"),
			value -> configValues.put("paletteTipDismissed", value));
		onOpened = tip::openedWith;
		PaletteHotkeyController controller = controller();
		controller.start();
		assertTrue(tip.shouldShow(configured.get()));
		palette.failOpen = true;
		registered.get(0).keyPressed(press(game, KeyEvent.VK_T, InputEvent.CTRL_DOWN_MASK));
		assertTrue(tip.shouldShow(configured.get()));
		assertFalse(configValues.containsKey("paletteTipDismissed"));
		controller.configurationChanged();
		palette.failOpen = false;
		registered.get(0).keyPressed(press(game, KeyEvent.VK_T, InputEvent.CTRL_DOWN_MASK));
		assertEquals(2, palette.opens);
		assertEquals("true", configValues.get("paletteTipDismissed"));
		assertFalse(tip.shouldShow(configured.get()));
		assertEquals(0, palette.routes);
	}

	private PaletteHotkeyController controller()
	{
		return new PaletteHotkeyController(configured::get, palette, onOpened,
			listener -> { registerCalls++; registered.add(listener); },
			listener -> { unregisterCalls++; registered.remove(listener); });
	}

	private static KeyEvent press(JPanel source, int code, int modifiers)
	{
		// Passed directly to a listener under test; never posted to an event queue.
		return new KeyEvent(source, KeyEvent.KEY_PRESSED, 1L, modifiers, code, KeyEvent.CHAR_UNDEFINED)
		{
			@Override public int getExtendedKeyCode() { return code; }
		};
	}

	private final class FakePalette implements PaletteHotkeyController.PaletteWindow
	{
		private boolean open;
		private int opens;
		private int closes;
		private int disposals;
		private int routes;
		private boolean failOpen;
		private Keybind localHotkey;

		@Override public boolean isOpen() { return open; }
		@Override public void open() { if (!failOpen) open = true; opens++; }
		@Override public void disposePalette() { open = false; disposals++; }
		@Override public boolean ownsKeyEvent(KeyEvent event) { return event.getSource() == searchField; }
		@Override public void configureHotkey(Keybind keybind) { localHotkey = keybind; }
		private void closeLocally() { open = false; closes++; }
	}
}

package com.example.palette;

import com.example.history.LearnedHistoryStore;
import com.example.history.TestHistoryStore;
import com.example.search.SearchMetadata;
import com.example.search.SearchService;
import java.awt.event.ActionEvent;
import java.awt.event.InputEvent;
import java.awt.event.KeyEvent;
import java.util.ArrayList;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import java.util.function.Consumer;
import javax.swing.Action;
import javax.swing.JComponent;
import javax.swing.JTextField;
import javax.swing.KeyStroke;
import javax.swing.SwingUtilities;
import net.runelite.api.coords.WorldPoint;
import net.runelite.client.config.Keybind;
import net.runelite.client.ui.components.IconTextField;
import org.junit.Test;

import static org.junit.Assert.*;

/** Exercises the actual input/action maps on IconTextField's focused child. */
public class PaletteKeyBindingsTest
{
	private final Map<String, String> values = new HashMap<>();
	private final LearnedHistoryStore history = TestHistoryStore.create(values);
	private final List<Selection> selections = new ArrayList<>();
	private final List<PaletteDestination> destinations = List.of(
		new PaletteDestination("a", "Chambers of Xeric", "Raids", new WorldPoint(1, 1, 0)),
		new PaletteDestination("b", "Chambers East", "Raids", new WorldPoint(2, 2, 0)));
	private int closes;
	private DestinationPaletteController controller;
	private IconTextField searchField;
	private JTextField focusedInput;
	private PaletteKeyBindings bindings;

	@Test
	public void focusedDefaultHotkeyClosesWithoutSelecting() throws Exception
	{
		onEdt(() ->
		{
			open();
			bindings.updateHotkey(new Keybind(KeyEvent.VK_T, InputEvent.CTRL_DOWN_MASK));
			assertEquals("paletteHotkeyClose", binding(KeyEvent.VK_T, InputEvent.CTRL_DOWN_MASK));
			press(KeyEvent.VK_T, InputEvent.CTRL_DOWN_MASK);
			assertEquals(1, closes);
			assertFalse(controller.isOpen());
			assertTrue(selections.isEmpty());
		});
	}

	@Test
	public void remapReplacesLocalBindingAndUnsetKeepsEscape() throws Exception
	{
		onEdt(() ->
		{
			open();
			bindings.updateHotkey(new Keybind(KeyEvent.VK_T, InputEvent.CTRL_DOWN_MASK));
			bindings.updateHotkey(new Keybind(KeyEvent.VK_G, InputEvent.CTRL_DOWN_MASK));
			assertNotEquals("paletteHotkeyClose", binding(KeyEvent.VK_T, InputEvent.CTRL_DOWN_MASK));
			assertEquals("paletteHotkeyClose", binding(KeyEvent.VK_G, InputEvent.CTRL_DOWN_MASK));
			press(KeyEvent.VK_G, InputEvent.CTRL_DOWN_MASK);
			assertEquals(1, closes);
			assertTrue(selections.isEmpty());

			open();
			bindings.updateHotkey(new Keybind(KeyEvent.VK_T, InputEvent.CTRL_DOWN_MASK));
			bindings.updateHotkey(Keybind.NOT_SET);
			assertNotEquals("paletteHotkeyClose", binding(KeyEvent.VK_T, InputEvent.CTRL_DOWN_MASK));
			press(KeyEvent.VK_ESCAPE);
			assertEquals(2, closes);
			assertTrue(selections.isEmpty());
		});
	}

	@Test
	public void remappingAwayFromAnActionKeyRestoresItsOriginalAction() throws Exception
	{
		onEdt(() ->
		{
			open();
			bindings.updateHotkey(new Keybind(KeyEvent.VK_ENTER, 0));
			assertEquals("paletteHotkeyClose", binding(KeyEvent.VK_ENTER, 0));
			bindings.updateHotkey(new Keybind(KeyEvent.VK_T, InputEvent.CTRL_DOWN_MASK));
			assertEquals("paletteEnter", binding(KeyEvent.VK_ENTER, 0));
			bindings.updateHotkey(new Keybind(KeyEvent.VK_CONTROL, InputEvent.CTRL_DOWN_MASK));
			assertEquals("paletteHotkeyClose", binding(KeyEvent.VK_CONTROL, InputEvent.CTRL_DOWN_MASK));
		});
	}

	@Test
	public void focusedEnterSelectsHighlightedResultOnceWithNormalizedQuery() throws Exception
	{
		onEdt(() ->
		{
			open();
			searchField.setText("  CHAMBERS!!  ");
			controller.queryChanged(searchField.getText());
			assertEquals(0, controller.getSelectedIndex());
			press(KeyEvent.VK_ENTER);
			press(KeyEvent.VK_ENTER); // pending dispatch cannot be duplicated
			assertEquals(1, selections.size());
			assertEquals(controller.getVisible().get(0).getId(), selections.get(0).destination.getId());
			assertEquals("chambers", selections.get(0).query);
			assertEquals(0, closes);
			selections.get(0).complete.accept(true);
			assertEquals(1, closes);
			assertFalse(controller.isOpen());
		});
	}

	@Test
	public void focusedEscapeClosesWithoutSelectingOrChangingHistory() throws Exception
	{
		onEdt(() ->
		{
			history.recordSelection("a", "");
			String before = values.get("history");
			open();
			press(KeyEvent.VK_ESCAPE);
			assertEquals(1, closes);
			assertFalse(controller.isOpen());
			assertTrue(selections.isEmpty());
			assertEquals(before, values.get("history"));
		});
	}

	@Test
	public void focusedArrowsWrapAndEmptyEnterPreservesLastDestinationRules() throws Exception
	{
		onEdt(() ->
		{
			history.recordSelection("b", "");
			history.recordSelection("a", "");
			open();
			assertEquals(0, controller.getSelectedIndex());
			press(KeyEvent.VK_DOWN);
			assertEquals(1, controller.getSelectedIndex());
			press(KeyEvent.VK_DOWN);
			assertEquals(0, controller.getSelectedIndex());
			press(KeyEvent.VK_UP);
			assertEquals(1, controller.getSelectedIndex());
			assertEquals("", searchField.getText());
			press(KeyEvent.VK_ENTER);
			assertEquals("b", selections.get(0).destination.getId());
			assertEquals("", selections.get(0).query);
		});
	}

	@Test
	public void emptyEnterRepeatsLastButRequiresNavigationWithoutValidLast() throws Exception
	{
		onEdt(() ->
		{
			history.recordSelection("a", "");
			open();
			press(KeyEvent.VK_ENTER);
			assertEquals("a", selections.get(0).destination.getId());
			assertEquals("", selections.get(0).query);
			selections.get(0).complete.accept(false);
			controller.closeWithoutSelection();

			history.recordSelection("stale", "");
			open();
			assertEquals(-1, controller.getSelectedIndex());
			press(KeyEvent.VK_ENTER);
			assertEquals(1, selections.size());
			press(KeyEvent.VK_DOWN);
			press(KeyEvent.VK_ENTER);
			assertEquals(2, selections.size());
			assertEquals("a", selections.get(1).destination.getId());
			assertEquals("", selections.get(1).query);
		});
	}

	private void open()
	{
		controller = new DestinationPaletteController(() -> destinations,
			new SearchService(new SearchMetadata(Map.of()), history), history,
			(destination, query, complete) -> selections.add(new Selection(destination, query, complete)),
			() -> closes++);
		searchField = new IconTextField();
		bindings = PaletteKeyBindings.install(searchField, () -> controller.moveSelection(1),
			() -> controller.moveSelection(-1), controller::confirm, controller::closeWithoutSelection);
		focusedInput = PaletteKeyBindings.findTextInput(searchField);
		assertNotNull(focusedInput);
		assertNotSame(searchField, focusedInput);
		controller.open();
	}

	private void press(int keyCode)
	{
		press(keyCode, 0);
	}

	private Object binding(int keyCode, int modifiers)
	{
		return focusedInput.getInputMap(JComponent.WHEN_FOCUSED)
			.get(KeyStroke.getKeyStroke(keyCode, modifiers));
	}

	private void press(int keyCode, int modifiers)
	{
		Object key = binding(keyCode, modifiers);
		assertNotNull("No focused-input binding for " + keyCode, key);
		Action action = focusedInput.getActionMap().get(key);
		assertNotNull(action);
		action.actionPerformed(new ActionEvent(focusedInput, ActionEvent.ACTION_PERFORMED, key.toString()));
	}

	private static void onEdt(Runnable action) throws Exception
	{
		SwingUtilities.invokeAndWait(action);
	}

	private static final class Selection
	{
		private final PaletteDestination destination;
		private final String query;
		private final Consumer<Boolean> complete;

		private Selection(PaletteDestination destination, String query, Consumer<Boolean> complete)
		{
			this.destination = destination;
			this.query = query;
			this.complete = complete;
		}
	}
}

package com.example.palette;

import org.junit.Test;

import java.awt.Dimension;
import java.awt.Rectangle;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertTrue;

public class PalettePositioningTest
{
	private static final Dimension DIALOG = new Dimension(560, 470);

	@Test
	public void centresOnStandardMonitorOneThirdDown()
	{
		Rectangle result = PalettePositioning.boundsFor(new Rectangle(0, 0, 1920, 1080), DIALOG);
		assertEquals(960, result.getCenterX(), 1);
		assertEquals(360, result.getCenterY(), 1);
	}

	@Test
	public void honoursNonzeroOriginsAndLeftOrRightMonitors()
	{
		for (Rectangle monitor : new Rectangle[]{
			new Rectangle(1920, 120, 1600, 900),
			new Rectangle(-1600, -100, 1600, 900)})
		{
			Rectangle result = PalettePositioning.boundsFor(monitor, DIALOG);
			assertEquals(monitor.getCenterX(), result.getCenterX(), 1);
			assertEquals(monitor.y + monitor.height / 3.0, result.getCenterY(), 1);
		}
	}

	@Test
	public void usesTaskbarReducedBounds()
	{
		Rectangle usable = new Rectangle(0, 40, 1920, 1000);
		Rectangle result = PalettePositioning.boundsFor(usable, DIALOG);
		assertEquals(960, result.getCenterX(), 1);
		assertEquals(40 + 1000 / 3.0, result.getCenterY(), 1);
	}

	@Test
	public void oversizedDialogIsClampedToUsableMonitor()
	{
		Rectangle usable = new Rectangle(-900, 80, 500, 300);
		Rectangle result = PalettePositioning.boundsFor(usable, new Dimension(800, 600));
		assertEquals(usable, result);
		assertTrue(usable.contains(result));
	}
}

package com.example.search;

import com.example.custom.CustomLocation;
import com.example.model.LocationDefinition;
import org.junit.Test;

import java.util.List;
import java.util.stream.Collectors;

import static org.junit.Assert.*;

public class SearchServiceTest
{
	private final SearchService search = new SearchService();

	@Test
	public void normalizesCaseWhitespaceAndPunctuation()
	{
		assertEquals("chambers of xeric", SearchService.normalize("  CHAMBERS   of\tXeric! "));
		assertEquals("seers village", SearchService.normalize("Seers' Village"));
		assertEquals("", SearchService.normalize(" -- "));
		assertEquals("", SearchService.normalize(null));
	}

	@Test
	public void ranksCanonicalTiersBeforeNameAndId()
	{
		List<SearchCandidate> candidates = List.of(
			new SearchCandidate("substring", "Old Prechambers Xeric Room"),
			new SearchCandidate("token", "Chambers of Xeric"),
			new SearchCandidate("prefix", "Chambers Xeric Lobby"),
			new SearchCandidate("exact", "Chambers Xeric")
		);

		List<SearchResult> results = search.search("chambers xeric", candidates);
		assertEquals(List.of("exact", "prefix", "token", "substring"), ids(results));
		assertEquals(List.of(MatchTier.EXACT, MatchTier.PREFIX, MatchTier.TOKEN, MatchTier.SUBSTRING),
			results.stream().map(SearchResult::getTier).collect(Collectors.toList()));
	}

	@Test
	public void substringStillMatchesInsideAName()
	{
		SearchResult result = search.search("ambers", List.of(new SearchCandidate("cox", "Chambers of Xeric"))).get(0);
		assertEquals(MatchTier.SUBSTRING, result.getTier());
	}

	@Test
	public void tokenMatchRequiresCompleteOrderedTokens()
	{
		SearchCandidate candidate = new SearchCandidate("cox", "Chambers of Xeric");
		assertEquals(MatchTier.TOKEN, search.search("chambers xeric", List.of(candidate)).get(0).getTier());
		assertTrue(search.search("ch x", List.of(candidate)).isEmpty());
		assertTrue(search.search("xeric chambers", List.of(candidate)).isEmpty());
	}

	@Test
	public void tiesUseNormalizedNameThenStableIdRegardlessOfInputOrder()
	{
		List<SearchCandidate> candidates = List.of(
			new SearchCandidate("z", "Farming Guild"),
			new SearchCandidate("b", "Farming Guild"),
			new SearchCandidate("a", "Farming Gate")
		);
		assertEquals(List.of("a", "b", "z"), ids(search.search("farming", candidates)));
		assertEquals(List.of("a", "b", "z"), ids(search.search("farming", List.of(candidates.get(2), candidates.get(0), candidates.get(1)))));
	}

	@Test
	public void emptyAndUnrelatedQueriesHaveNoRankedResults()
	{
		List<SearchCandidate> candidates = List.of(new SearchCandidate("id", "Chambers of Xeric"));
		assertTrue(search.search("  ", candidates).isEmpty());
		assertTrue(search.search("unrelated", candidates).isEmpty());
	}

	@Test
	public void builtInAndCustomDestinationsUseTheSameNameMatcher()
	{
		LocationDefinition builtIn = new LocationDefinition("dungeons:chambers-of-xeric", "Chambers of Xeric", 1, 2, 0);
		CustomLocation custom = new CustomLocation("custom:one", "Chambers of Xeric", "custom", 3, 4, 0);
		List<SearchResult> results = search.search("Chambers of Xeric", List.of(
			new SearchCandidate(custom.getId(), custom.getName()),
			new SearchCandidate(builtIn.getId(), builtIn.getName())
		));
		assertEquals(List.of("custom:one", "dungeons:chambers-of-xeric"), ids(results));
		assertEquals(MatchTier.EXACT, results.get(0).getTier());
		assertEquals(MatchTier.EXACT, results.get(1).getTier());
	}

	private static List<String> ids(List<SearchResult> results)
	{
		return results.stream().map(SearchResult::getId).collect(Collectors.toList());
	}
}

